#      06 시트의 '★ 포트(동일가중)' 행은 내가 **리포트 단계에서 사후로** 28로 나눠 만든 것이라
#      엔진이 집행한 비중이 아니었다. 즉 **리포트와 엔진이 다른 포트를 말하고 있었다.**
#    (D2) ★★ **배분층 build_allocation() 신설** — 전체자산 1.0을 종목에 나눠 담고, 행 합계가 1을
