#      P11 +0.0052 · P12 +0.0194(P2가 끌고 있다). "200일선이 늦다"는 진단은 맞았지만 **창을 줄이는
#      처방은 틀렸다** — 개별 주식에서 가격 기반 하락 예측은 창 길이를 바꿔도 안 된다.
