#      ★ 그런데 **점화 빈도를 보지 않았다.** 분위 버킷 규칙은 **정의상** 33%의 날에 켜진다.
#        합집합 ≈ 1 − 0.67×0.67×0.85 ≈ **0.6** → **60%의 날을 잘라낸다.**
#      합성 데이터 실측: 평균노출 **0.4942**, 즉 대체하려던 ext200(**0.5866**)보다 **더 낮다.**
#      사용자 요구는 "상승을 타서 비중 최대로"인데 v0.2.0은 **요구와 반대 방향**이었다.
