# 테스트·오프라인 주입용(기본 None = yfinance). callable(ticker) → dict(sector, industry, shortName)
INFO_FETCHER_OVERRIDE: Optional[Any] = None


def normalize_ticker(t: Any) -> str:
    """입력 티커 정규화 — 대문자·공백/$ 제거·'.'→'-'(Yahoo 표기: BRK.B → BRK-B). 빈 문자열이면 ''."""
    s = str(t or "").strip().upper().replace("$", "").replace(" ", "")
    return s.replace(".", "-")


def resolve_universe(cfg: "StockConfig") -> Dict[str, Any]:
    """역할별 티커 목록. 반환 {main: [..](설계 또는 사용자 입력 + 추가), holdout: [..], role: {티커: 역할}, registered: {티커: ETF},
    dropped: [(원문, 사유)]}. 역할 = '설계'(사전등록 29) · '사용자'(TICKERS/EXTRA_TICKERS) · '홀드아웃'(검증 전용).
    홀드아웃과 겹치는 사용자 티커는 **사용자**로 본다(사용자가 예측을 원한 종목) — 그 티커는 홀드아웃 집합에서 빠진다(00·20에 표시)."""
    reg: Dict[str, str] = {}
    for etf, tk in dict(getattr(cfg, "UNIVERSE", STOCK_UNIVERSE) or {}).items():
        reg[normalize_ticker(tk)] = etf
    hold_reg = {normalize_ticker(tk): etf for etf, tk in STOCK_HOLDOUT.items()}
    role: Dict[str, str] = {}
    dropped: List[Tuple[str, str]] = []
    user_in = tuple(getattr(cfg, "TICKERS", ()) or ())
    extra_in = tuple(getattr(cfg, "EXTRA_TICKERS", ()) or ())
    main: List[str] = []
    if user_in:
        for raw in user_in:
            t = normalize_ticker(raw)
            if not t:
                dropped.append((str(raw), "빈 티커")); continue
            if t in role:
                dropped.append((str(raw), "중복")); continue
            role[t] = "사용자"; main.append(t)
    else:
        for t in sorted(reg):
            role[t] = "설계"; main.append(t)
    for raw in extra_in:
        t = normalize_ticker(raw)
        if not t:
            dropped.append((str(raw), "빈 티커")); continue
        if t in role:
            dropped.append((str(raw), f"중복(이미 {role[t]})")); continue
        role[t] = "사용자"; main.append(t)
    holdout: List[str] = []
    if bool(getattr(cfg, "GENERALIZATION_CHECK", True)):
        for raw in tuple(getattr(cfg, "HOLDOUT_TICKERS", ()) or ()):
            t = normalize_ticker(raw)
            if not t or t in role:
                if t in role:
                    dropped.append((str(raw), f"홀드아웃에서 제외(이미 {role[t]} 종목)"))
                continue
            role[t] = "홀드아웃"; holdout.append(t)
    registered = {**{t: e for t, e in hold_reg.items() if t in role}, **{t: e for t, e in reg.items() if t in role}}
    log("RUN", kv(event="universe_resolved", main=len(main), holdout=len(holdout),
                  design=sum(1 for v in role.values() if v == "설계"), user=sum(1 for v in role.values() if v == "사용자"),
                  dropped=(";".join(f"{a}:{b}" for a, b in dropped)[:200] or "-")))
    return {"main": main, "holdout": holdout, "role": role, "registered": registered, "dropped": dropped}


def _yahoo_info(t: str) -> Dict[str, Any]:
    if INFO_FETCHER_OVERRIDE is not None:
        return dict(INFO_FETCHER_OVERRIDE(t) or {})
    import yfinance as yf
    inf = yf.Ticker(t).info or {}
    return {"sector": inf.get("sector"), "industry": inf.get("industry"),
            "shortName": inf.get("shortName") or inf.get("longName"), "quoteType": inf.get("quoteType")}


def map_by_yahoo(sector: Any, industry: Any) -> Tuple[Optional[str], str]:
    """Yahoo 업종 → 산업 ETF(표 첫 일치) · 없으면 섹터 → 섹터 ETF. (ETF, 방법) — 못 찾으면 (None, '-')."""
    ind = str(industry or "").strip().lower()
    if ind:
        for key, etf in YAHOO_INDUSTRY_TO_ETF:
            if key in ind:
                return etf, "Yahoo 업종"
    sec = str(sector or "").strip().lower()
    if sec in YAHOO_SECTOR_TO_ETF:
        return YAHOO_SECTOR_TO_ETF[sec], "Yahoo 섹터"
    return None, "-"


def auto_map_industry(tickers: List[str], registered: Dict[str, str], cfg: "StockConfig",
                      prices: Optional[Dict[str, pd.DataFrame]] = None,
                      etf_prices: Optional[Dict[str, pd.DataFrame]] = None) -> Dict[str, Dict[str, Any]]:
    """티커 → {etf, method, sector, industry, name, corr}. 순서: 사전등록 → Yahoo 업종·섹터(캐시 AUTO_MAP_CACHE_DAYS) →
    상관 폴백(etf_prices 필요 · 평가창 시작 **전** AUTO_MAP_CORR_WIN일 — 전 이력이 평가창 뒤에서 시작하면 첫 N일을 쓰고 ⚠ 표시) → 미분류.
    실패는 전부 사유로 남는다(무음 금지)."""
    out: Dict[str, Dict[str, Any]] = {}
    cp = _cache_path(cfg, "automap.json")
    cache: Dict[str, Any] = {}
    try:
        if os.path.exists(cp) and _cache_fresh(cp, int(getattr(cfg, "AUTO_MAP_CACHE_DAYS", 30))):
            with open(cp, "r", encoding="utf-8") as fh:
                cache = json.load(fh) or {}
    except Exception as e:
        log("MAP", kv(event="automap_cache_read_failed", err=type(e).__name__), level="warning")
        cache = {}
    need_info = [t for t in tickers if t not in registered and bool(getattr(cfg, "AUTO_MAP", True))]
    fetched = 0
    for t in tickers:
        if t in registered:
            out[t] = {"etf": registered[t], "method": "사전등록", "sector": "-", "industry": "-",
                      "name": STOCK_NAME_KR.get(t, t), "corr": None}
            continue
        rec = {"etf": None, "method": "미분류", "sector": None, "industry": None, "name": STOCK_NAME_KR.get(t, t), "corr": None}
        if t in need_info:
            info = cache.get(t)
            if info is None:
                try:
                    info = _yahoo_info(t); fetched += 1
                    cache[t] = info
                except Exception as e:
                    info = {"error": f"{type(e).__name__}: {str(e)[:80]}"}      # 실패는 캐시하지 않는다(다음 실행 재시도)
            rec["sector"], rec["industry"] = info.get("sector"), info.get("industry")
            if info.get("shortName"):
                rec["name"] = str(info.get("shortName"))[:40]
            etf, how = map_by_yahoo(info.get("sector"), info.get("industry"))
            if etf:
                rec["etf"], rec["method"] = etf, how
            elif info.get("error"):
                rec["method"] = f"미분류(info 실패: {info['error'][:40]})"
        out[t] = rec
    # 상관 폴백 — Yahoo가 못 준 티커만
    todo = [t for t, r in out.items() if r["etf"] is None]
    if todo and prices and etf_prices:
        win = int(getattr(cfg, "AUTO_MAP_CORR_WIN", 504))
        min_c = float(getattr(cfg, "AUTO_MAP_MIN_CORR", 0.30))
        ev0 = pd.Timestamp(cfg.EVAL_START)
        E = pd.DataFrame({e: pd.to_numeric(d["Close"], errors="coerce") for e, d in etf_prices.items()
                          if isinstance(d, pd.DataFrame) and "Close" in d.columns}).pct_change(fill_method=None)
        for t in todo:
            if t not in prices:
                continue
            r = pd.to_numeric(prices[t]["Close"], errors="coerce").pct_change(fill_method=None)
            pre = r[r.index < ev0].dropna()
            flag = ""
            if len(pre) >= 252:
                seg = pre.iloc[-win:]
            else:
                seg = r.dropna().iloc[:win]
                flag = " ⚠ 평가창 이전 이력 부족 → 첫 구간 사용(평가창 자료)"
            if len(seg) < 126:
                out[t]["method"] = "미분류(상관 표본 부족)"
                continue
            c = E.reindex(seg.index).corrwith(seg).dropna()
            if not len(c):
                continue
            ind_c = c[[e for e in c.index if e not in SECTOR_ETFS]]
            best = (ind_c.idxmax() if len(ind_c) else c.idxmax())
            if float(c.get(best, np.nan)) < min_c and len(c):
                best = c.idxmax()
            if float(c[best]) >= min_c:
                out[t].update({"etf": str(best), "method": f"상관 폴백(ρ={float(c[best]):.2f}){flag}", "corr": round(float(c[best]), 3)})
            else:
                out[t]["method"] = f"미분류(최대 상관 {float(c.max()):.2f} < {min_c:.2f})"
    try:
        with open(cp, "w", encoding="utf-8") as fh:
            json.dump(cache, fh, ensure_ascii=False)
    except Exception as e:
        log("MAP", kv(event="automap_cache_write_failed", err=type(e).__name__), level="warning")
    log("MAP", kv(event="auto_map_done", tickers=len(tickers), registered=sum(1 for r in out.values() if r["method"] == "사전등록"),
                  yahoo=sum(1 for r in out.values() if str(r["method"]).startswith("Yahoo")),
                  corr=sum(1 for r in out.values() if str(r["method"]).startswith("상관")),
                  unmapped=sum(1 for r in out.values() if r["etf"] is None), info_fetched=fetched,
                  detail=";".join(f"{t}={r['etf'] or '-'}({r['method'][:10]})" for t, r in out.items()
                                  if r["method"] != "사전등록")[:300] or "-"))
    return out


def _seg_capture(ret: pd.Series, w: pd.Series, cfg: "StockConfig", I=None) -> Tuple[float, float]:
    """상승 포착률 · 하락 노출률(00D 블록 A와 같은 연속 지표 — B&H 곡선 지그재그 SEG_MIN_MOVE). I 없으면 (nan, nan)."""
    if I is None or not hasattr(I, "zigzag_segments"):
        return float("nan"), float("nan")
    r = pd.to_numeric(ret, errors="coerce").fillna(0.0)
    ww = pd.to_numeric(w, errors="coerce").reindex(r.index).fillna(0.0).clip(0.0, 1.0)
    cur = (1.0 + r).cumprod()
    segs = I.zigzag_segments(cur, float(getattr(cfg, "SEG_MIN_MOVE", 0.10)), int(getattr(cfg, "SEG_MIN_DAYS", 3)))
    up_c = up_t = dn_c = dn_t = 0.0
    rv, wv = r.to_numpy(), ww.to_numpy()
    for kind, a, b in segs or []:
        rs, ws = rv[a + 1:b + 1], wv[a + 1:b + 1]
        if kind.startswith("하락"):
            dn_c += float((ws * rs).sum()); dn_t += float(rs.sum())
        else:
            up_c += float((ws * rs).sum()); up_t += float(rs.sum())
    return (up_c / up_t if abs(up_t) > 1e-12 else float("nan")), (dn_c / dn_t if abs(dn_t) > 1e-12 else float("nan"))


def _perf3(r: pd.Series) -> Tuple[float, float, float]:
    r = pd.to_numeric(r, errors="coerce").fillna(0.0)
    if not len(r):
        return float("nan"), float("nan"), float("nan")
    cur = (1.0 + r).cumprod()
    yrs = max(len(r) / 252.0, 1e-9)
    cg = float(cur.iloc[-1]) ** (1.0 / yrs) - 1.0
    mdd = float((cur / cur.cummax() - 1.0).min())
    return cg, mdd, (cg / abs(mdd) if mdd < -1e-9 else float("nan"))


def build_generalization_sheet(res: Dict[str, Any], I=None) -> Tuple[pd.DataFrame, str]:
    """[20_일반화검증] A 집합별 요약(설계·홀드아웃·사용자) · B 종목별 · C ML 티커 제외 교차검증 · D 판정(사전등록).
    같은 라이브 규칙(min(base1_cut, M E_t))을 **설계에 쓰지 않은 종목**에 그대로 적용해 개선이 재현되는지 본다."""
    cfg = res.get("cfg", CFG)
    A, B, C, D = ("A. 집합별 요약(같은 규칙 · 같은 E_t · 평가창)", "B. 종목별", "C. ML 티커 제외 교차검증(설계 종목으로만 학습)",
                  "D. 판정(사전등록)")
    rows: List[dict] = []
    role = res.get("roles") or {}
    amap = res.get("automap") or {}
    sets: Dict[str, Dict[str, Tuple[pd.DataFrame, pd.DataFrame]]] = {"설계": {}, "사용자": {}, "홀드아웃": {}}
    for t in sorted(res.get("panel") or {}):
        sets.setdefault(role.get(t, "설계"), {})[t] = (res["panel"][t], res["pos"][t])
    for t in sorted(res.get("panel_h") or {}):
        sets["홀드아웃"][t] = (res["panel_h"][t], res["pos_h"][t])
    rows.append({"블록": A, "집합": "── 읽는 법 ──",
                 "판정": ("홀드아웃 = 설계(규칙 선택·임계값·과거 라운드 판단)에 한 번도 쓰지 않은 사전등록 종목(산업마다 1개). "
                        "같은 라이브 규칙과 같은 M 시장 예산을 그대로 적용해 '설계 종목에서 본 개선(하락 회피·칼마)이 처음 보는 종목에서도 "
                        "나오는가'를 잰다. 홀드아웃은 배분 포트·06 포트·00D에 넣지 않는다(오염 방지). 사용자 = TICKERS/EXTRA_TICKERS로 입력한 종목. "
                        "칼마 = CAGR/|MDD| · 상승 포착률 = 상승구간 번 몫/B&H(오라클 100%) · 하락 노출률 = 하락구간 잃은 몫/B&H(오라클 0%). "
                        "판정 기준(사전등록): ① 홀드아웃 칼마 개선 비율 ≥ 설계 비율 − GEN_PASS_SHARE_GAP ② 홀드아웃 중위 Δ칼마 > 0 "
                        "③ 홀드아웃 동일가중 포트 MDD 개선. 연구·교육용, 투자 자문 아님.")})
    summ: Dict[str, Dict[str, float]] = {}
    for nm, S_ in sets.items():
        if not S_:
            continue
        per = []
        live_R, bh_R = {}, {}
        for t, (pnl, ps) in S_.items():
            rb = pd.to_numeric(pnl["일간수익"], errors="coerce").fillna(0.0)
            rl = pd.to_numeric(ps["전략일간수익"], errors="coerce").reindex(rb.index).fillna(0.0)
            w = pd.to_numeric(ps["집행비중"], errors="coerce").reindex(rb.index)
            cb, mb, kb = _perf3(rb)
            cl, ml_, kl = _perf3(rl)
            upc, dne = _seg_capture(rb, w, cfg, I)
            live_R[t], bh_R[t] = rl, rb
            e = amap.get(t, {})
            per.append({"블록": B, "집합": nm, "티커": t, "이름": e.get("name", STOCK_NAME_KR.get(t, t)),
                        "산업ETF": e.get("etf") or res.get("parent_of", {}).get(t, "") or "-", "매핑 방법": e.get("method", "-"),
                        "관측일": int(len(rb)), "평균 노출": round(float(w.mean()), 4) if len(w) else None,
                        "B&H CAGR": round(cb, 4), "라이브 CAGR": round(cl, 4), "B&H MDD": round(mb, 4), "라이브 MDD": round(ml_, 4),
                        "B&H 칼마": (round(kb, 3) if kb == kb else None), "라이브 칼마": (round(kl, 3) if kl == kl else None),
                        "Δ칼마": (round(kl - kb, 3) if kl == kl and kb == kb else None),
                        "칼마 개선": bool(kl == kl and kb == kb and kl > kb), "MDD 개선": bool(ml_ > mb),
                        "상승 포착률": (round(upc, 3) if upc == upc else None), "하락 노출률": (round(dne, 3) if dne == dne else None),
                        "E3 가능(어닝 자료)": bool(pd.to_numeric(pnl.get("어닝_서프라이즈%"), errors="coerce").notna().any())
                        if "어닝_서프라이즈%" in pnl.columns else False})
        rows.extend(per)
        P_ = pd.DataFrame(per)
        LR = pd.DataFrame(live_R).fillna(0.0).mean(axis=1)
        BR = pd.DataFrame(bh_R).fillna(0.0).mean(axis=1)
        pc, pm, pk = _perf3(LR)
        bc, bm, bk = _perf3(BR)
        s = {"n": len(per), "share_cal": float(P_["칼마 개선"].mean()), "share_mdd": float(P_["MDD 개선"].mean()),
             "med_dcal": float(pd.to_numeric(P_["Δ칼마"], errors="coerce").median()),
             "port_mdd_l": pm, "port_mdd_b": bm, "port_cal_l": pk, "port_cal_b": bk}
        summ[nm] = s
        rows.append({"블록": A, "집합": nm, "종목 수": len(per),
                     "칼마 개선 비율": round(s["share_cal"], 3), "MDD 개선 비율": round(s["share_mdd"], 3),
                     "중위 B&H 칼마": round(float(pd.to_numeric(P_["B&H 칼마"], errors="coerce").median()), 3),
                     "중위 라이브 칼마": round(float(pd.to_numeric(P_["라이브 칼마"], errors="coerce").median()), 3),
                     "중위 Δ칼마": round(s["med_dcal"], 3),
                     "중위 B&H MDD": round(float(P_["B&H MDD"].median()), 4), "중위 라이브 MDD": round(float(P_["라이브 MDD"].median()), 4),
                     "중위 B&H CAGR": round(float(P_["B&H CAGR"].median()), 4), "중위 라이브 CAGR": round(float(P_["라이브 CAGR"].median()), 4),
                     "중위 상승 포착률": round(float(pd.to_numeric(P_["상승 포착률"], errors="coerce").median()), 3),
                     "중위 하락 노출률": round(float(pd.to_numeric(P_["하락 노출률"], errors="coerce").median()), 3),
                     "동일가중 포트 B&H CAGR/MDD/칼마": f"{bc:.4f} / {bm:.4f} / {bk:.3f}",
                     "동일가중 포트 라이브 CAGR/MDD/칼마": f"{pc:.4f} / {pm:.4f} / {pk:.3f}"})
    # ---- C. ML 티커 제외 교차검증 ----
    ml_line = "생략"
    if bool(getattr(cfg, "GEN_ML_LTO", True)) and I is not None and hasattr(I, "build_ml_panel") and summ.get("홀드아웃"):
        try:
            from sklearn.ensemble import HistGradientBoostingClassifier
            prices = res.get("prices") or {}
            des = [t for t in (res.get("panel") or {}) if t in prices]
            hol = [t for t in (res.get("panel_h") or {}) if t in prices]
            curves = {t: pd.to_numeric(prices[t]["Close"], errors="coerce") for t in des + hol}
            dr = pd.DataFrame({t: curves[t].pct_change(fill_method=None) for t in des})
            mkt = (1.0 + dr.mean(axis=1).fillna(0.0)).cumprod()        # 시장 대용 = **설계 종목만** 동일가중
            H = int(getattr(cfg, "ML_HORIZON", 21))
            Pn = I.build_ml_panel(curves, res.get("market_w"), mkt, H)
            Pn["y"] = (Pn["fwd"] > 0).astype(float).where(Pn["fwd"].notna())
            feats = [c for c in Pn.columns if c not in ("date", "asset", "fwd", "y")]
            seed = int(getattr(cfg, "ML_SEED", 20260920))
            prm = dict(max_depth=3, learning_rate=0.05, max_iter=200, min_samples_leaf=300, l2_regularization=1.0,
                       early_stopping=False, random_state=seed)
            dates = np.sort(Pn["date"].unique())
            y0 = int(pd.Timestamp(cfg.EVAL_START).year)
            mny = int(getattr(cfg, "ML_MIN_TRAIN_YEARS", 3))
            fy = max(y0, int(pd.Timestamp(dates[0]).year) + mny)
            aucs = {"설계(표본 밖 연도)": [], "홀드아웃(처음 보는 종목)": []}
            ys_d, ps_d, ys_h, ps_h = [], [], [], []
            for Y in range(fy, int(pd.Timestamp(dates[-1]).year) + 1):
                ts = pd.Timestamp(f"{Y}-01-01")
                di = int(np.searchsorted(dates, np.datetime64(ts)))
                if di - H - 1 < 0:
                    continue
                emb = pd.Timestamp(dates[di - H - 1])
                tr = Pn[(Pn["date"] <= emb) & Pn["y"].notna() & Pn["asset"].isin(des)]
                if len(tr) < 2000 or tr["y"].nunique() < 2:
                    continue
                m = HistGradientBoostingClassifier(**prm).fit(tr[feats], tr["y"])
                te = Pn[(Pn["date"] >= ts) & (Pn["date"] <= pd.Timestamp(f"{Y}-12-31")) & Pn["y"].notna()]
                for grp, lst, ys, ps in (("설계(표본 밖 연도)", des, ys_d, ps_d), ("홀드아웃(처음 보는 종목)", hol, ys_h, ps_h)):
                    g = te[te["asset"].isin(lst)]
                    if not len(g) or g["y"].nunique() < 2:
                        continue
                    p = m.predict_proba(g[feats])[:, 1]
                    ys.append(g["y"].values); ps.append(p)
                    a = I._auc_score(g["y"].values, p) if hasattr(I, "_auc_score") else float("nan")
                    ae = I._auc_score(g["y"].values, g["E"].values) if ("E" in g.columns and hasattr(I, "_auc_score")) else float("nan")
                    aucs[grp].append(a)
                    rows.append({"블록": C, "집합": grp, "연도": int(Y), "학습(설계 종목)": f"~{emb.date()} · {len(tr):,}행",
                                 "시험 행": int(len(g)), "AUC ML": round(a, 4) if a == a else None,
                                 "AUC E_t 단독": round(ae, 4) if ae == ae else None})
            tot = {}
            for grp, ys, ps in (("설계(표본 밖 연도)", ys_d, ps_d), ("홀드아웃(처음 보는 종목)", ys_h, ps_h)):
                if ys:
                    tot[grp] = I._auc_score(np.concatenate(ys), np.concatenate(ps))
                    rows.append({"블록": C, "집합": grp, "연도": "전체", "AUC ML": round(tot[grp], 4),
                                 "판정": ("0.5 = 동전 — ML은 진단 전용(라이브 아님)")})
            if len(tot) == 2:
                gap = tot["홀드아웃(처음 보는 종목)"] - tot["설계(표본 밖 연도)"]
                ml_line = (f"ML AUC 설계 {tot['설계(표본 밖 연도)']:.4f} vs 처음 보는 종목 {tot['홀드아웃(처음 보는 종목)']:.4f}"
                           f"(차 {gap:+.4f} — {'종목이 바뀌어도 같은 수준' if abs(gap) <= 0.02 else '⚠ 종목 의존'})")
        except Exception as e:
            ml_line = f"ML 교차검증 실패 {type(e).__name__}: {str(e)[:100]}"
            log("REPORT", kv(event="gen_ml_lto_failed", err=type(e).__name__, msg=str(e)[:160]), level="warning")
    # ---- D. 판정 ----
    gap_ok = float(getattr(cfg, "GEN_PASS_SHARE_GAP", 0.15))
    d_, h_ = summ.get("설계"), summ.get("홀드아웃")
    if d_ and h_:
        c1 = h_["share_cal"] >= d_["share_cal"] - gap_ok
        c2 = h_["med_dcal"] > 0
        c3 = h_["port_mdd_l"] > h_["port_mdd_b"]
        ok_all = c1 and c2 and c3
        line = (("✓ 일반화 통과" if ok_all else "✗ 일반화 미달 — 설계 종목에만 맞는 규칙일 수 있다")
                + f" · 칼마 개선 비율 설계 {d_['share_cal']:.2f} vs 홀드아웃 {h_['share_cal']:.2f}({'O' if c1 else 'X'})"
                + f" · 홀드아웃 중위 Δ칼마 {h_['med_dcal']:+.3f}({'O' if c2 else 'X'})"
                + f" · 홀드아웃 포트 MDD {h_['port_mdd_b']:.3f}→{h_['port_mdd_l']:.3f}({'O' if c3 else 'X'})"
                + f" · {ml_line}")
    elif d_ or summ.get("사용자"):
        line = "홀드아웃 없음(GENERALIZATION_CHECK=False 또는 다운로드 실패) — 판정 불가 · " + ml_line
    else:
        line = "산출 불가(종목 없음)"
    for nm in ("사용자",):
        u = summ.get(nm)
        if u:
            line += f" | 사용자 입력 {u['n']}종목: 칼마 개선 {u['share_cal']:.2f} · 중위 Δ칼마 {u['med_dcal']:+.3f}"
    rows.append({"블록": D, "집합": "판정", "판정": line})
    log("REPORT", kv(event="generalization_ready", line=line[:300]),
        level=("info" if line.startswith("✓") else "warning"))
    return pd.DataFrame(rows), line


# =============================================================================
# [2] 특성 — 전부 t일까지의 정보로만 만든다
#     규약: 단면 비교가 필요한 값은 **자기이력 expanding 백분위**로 정규화한다
#           (정적 전이력 값으로 줄세우면 '정체성'을 줄세우는 셈 — I 계층 라운드53의 교훈).
# =============================================================================
def _own_pct(s: pd.Series, min_hist: int) -> pd.Series:
    """자기이력 expanding 백분위 — t일까지의 자기 분포에서 오늘 값의 위치(0~1). 룩어헤드 없음."""
    return pd.Series(s).astype(float).expanding(min_periods=int(min_hist)).rank(pct=True)


def build_price_features(df: pd.DataFrame, cfg: StockConfig) -> pd.DataFrame:
    """[K2] 가격 특성. 입력은 한 티커의 OHLCV, 출력은 같은 색인의 특성 표.
    모든 열이 **그날까지의 값만** 쓴다(rolling·expanding·shift만 사용 · center=False)."""
    px = pd.to_numeric(df["Close"], errors="coerce")
    hi = pd.to_numeric(df.get("High", px), errors="coerce")
    lo = pd.to_numeric(df.get("Low", px), errors="coerce")
    r = px.pct_change()
    mh = int(cfg.OWN_PCT_MIN_HIST)
    out = pd.DataFrame(index=df.index)
    out["종가"] = px
    out["일간수익"] = r
    ma = px.rolling(int(cfg.MA_LONG), min_periods=int(cfg.MA_LONG * 0.75)).mean()
    out["ext200"] = px / ma - 1.0
    out["ext200_pct"] = _own_pct(out["ext200"], mh)
    for w in (21, 63, 126):
        out[f"mom{w}"] = px / px.shift(w) - 1.0
        out[f"mom{w}_pct"] = _own_pct(out[f"mom{w}"], mh)
    vol = r.rolling(int(cfg.VOL_WIN), min_periods=int(cfg.VOL_WIN * 0.75)).std() * math.sqrt(252.0)
    out["vol21"] = vol
    out["vol21_pct"] = _own_pct(vol, mh)
    roll_max = px.rolling(int(cfg.DD_WIN), min_periods=int(cfg.DD_WIN * 0.5)).max()
    out["dd63"] = px / roll_max - 1.0
    out["dd63_pct"] = _own_pct(out["dd63"], mh)
    # Parkinson 변동성(고가-저가) — 종가 변동성이 못 보는 장중 폭을 잡는다
    with np.errstate(invalid="ignore", divide="ignore"):
        park = np.log(hi / lo) ** 2
    park5 = pd.Series(park, index=df.index).rolling(5, min_periods=3).mean()
    out["park5"] = np.sqrt(park5 / (4.0 * math.log(2.0)) * 252.0)
    out["park5_pct"] = _own_pct(out["park5"], mh)
    out["거래대금21_pct"] = _own_pct((px * pd.to_numeric(df.get("Volume", np.nan), errors="coerce"))
                                  .rolling(21, min_periods=15).mean(), mh)
    # ---- [v0.2.0 K3] 빠른 방어 특성 — 200일선이 양쪽에서 늦다는 진단의 대응(전부 t일까지의 정보) ----
    ma20 = px.rolling(20, min_periods=15).mean()
    out["ma20_ext"] = px / ma20 - 1.0
    _above = (px > ma20)
    out["ma20_cross_dn"] = (_above.shift(1).fillna(False) & ~_above).astype(float)   # 하향 교차 당일만 1
    out["ret5"] = px / px.shift(5) - 1.0
    out["ret5_pct"] = _own_pct(out["ret5"], mh)
    # ATR(14) 트레일링 스톱 — 최근 63일 고가에서 3 ATR 아래로 내려온 날. 전부 과거 값만 쓴다.
    _tr = pd.concat([(hi - lo), (hi - px.shift(1)).abs(), (lo - px.shift(1)).abs()], axis=1).max(axis=1)
    atr = _tr.rolling(14, min_periods=10).mean()
    out["atr14"] = atr
    _peak = px.rolling(63, min_periods=30).max()
    out["atr_trail_break"] = ((px < (_peak - 3.0 * atr)) & atr.notna()).astype(float)
    return out


# ---- 손익계산서 항목명 후보(yfinance 버전·티커마다 다르다 → 순서대로 찾는다) ----
_REV_KEYS = ("Total Revenue", "TotalRevenue", "Operating Revenue", "Revenues")
_OPI_KEYS = ("Operating Income", "OperatingIncome", "Total Operating Income As Reported")
_NI_KEYS = ("Net Income", "NetIncome", "Net Income Common Stockholders",
            "Net Income Continuous Operations")
_EPS_KEYS = ("Diluted EPS", "DilutedEPS", "Basic EPS", "BasicEPS")


def _pick(df: pd.DataFrame, keys: Tuple[str, ...], fuzzy: Tuple[str, ...] = ()
          ) -> Tuple[Optional[pd.Series], str]:
    """항목을 고르고 **무엇을 골랐는지 이름까지 돌려준다**(02 시트에 남겨 첫 실행에서 확인할 수 있게).

    ⚠ 왜 퍼지 매칭까지 두는가: yfinance 버전·티커마다 손익계산서 항목 이름이 다르다
      ("Total Revenue" / "TotalRevenue" / "Operating Revenue" …). 정확 매칭만 두면 어떤 티커에서
      **조용히 NaN**이 되고, 그러면 펀더멘탈 규칙이 '측정 불가'인데 '효과 없음'처럼 보인다.
      그래서 (1) 정확 매칭 → (2) 부분 문자열 매칭 순으로 찾고 고른 이름을 로그·시트에 남긴다."""
    for k in keys:
        if k in df.columns:
            s = pd.to_numeric(df[k], errors="coerce")
            if s.notna().sum() >= 4:
                return s, str(k)
    for pat in (fuzzy or ()):
        for c in df.columns:
            if str(pat).lower() in str(c).lower():
                s = pd.to_numeric(df[c], errors="coerce")
                if s.notna().sum() >= 4:
                    return s, f"{c}(퍼지:{pat})"
    return None, "-"


def build_fundamental_asof(rec: Dict[str, Any], idx: pd.DatetimeIndex, cfg: StockConfig
                           ) -> Tuple[pd.DataFrame, pd.DataFrame]:
    """[K3 ★] 분기 재무를 **유효일(발표일) 기준 as-of**로 일별 특성으로 펼친다.

    반환 (일별 특성, 분기 원장). 분기 원장에는 기간말·유효일·유효일 출처가 남아 감사가 가능하다.

    ★ 인과 처리(이 함수가 이 파일의 핵심 안전장치다):
      유효일 = (a) 그 분기에 대응하는 **실제 발표일**이 있으면 그 날
               (b) 없으면 **기간말 + FUND_PUBLISH_LAG_DAYS**
      그리고 as-of 조인으로 '유효일 ≤ t'인 가장 최근 분기만 t일에 넣는다.
      (a)의 대응 규칙: 기간말 이후 **가장 가까운** 발표일. 기간말보다 이른 발표일은 그 분기 것이 아니다.
      ⚠ 'YoY'는 4분기 전 대비다 — 분기 수가 5개 미만이면 성장률 열은 전부 NaN으로 남긴다(추정하지 않는다)."""
    q = rec.get("q")
    earn = rec.get("earn")
    empty = pd.DataFrame(index=idx)
    ledger = pd.DataFrame()
    # ⚠ 방향 방어 — download_fundamentals가 이미 전치해서 (기간말 × 항목)으로 넘기지만, yfinance 버전에
    #   따라 이미 그 방향으로 오는 경우가 있다. 색인이 날짜처럼 보이지 않으면 한 번 더 전치한다.
    if isinstance(q, pd.DataFrame) and len(q):
        _idx_dt = pd.to_datetime(pd.Series(q.index), errors="coerce").notna().mean()
        _col_dt = pd.to_datetime(pd.Series(q.columns), errors="coerce").notna().mean()
        if _col_dt > 0.8 and _idx_dt < 0.5:
            q = q.T
            q.index = pd.to_datetime(q.index, errors="coerce")
            q = q[q.index.notna()].sort_index()
    if not isinstance(q, pd.DataFrame) or not len(q):
        for c in ["매출_YoY", "EPS_YoY", "영업이익률", "영업이익률_변화", "매출성장_가속",
                  "펀더멘탈_분기수"]:
            empty[c] = np.nan
        return empty, ledger
    rev, _n_rev = _pick(q, _REV_KEYS, ("revenue", "sales"))
    opi, _n_opi = _pick(q, _OPI_KEYS, ("operating income",))
    ni, _n_ni = _pick(q, _NI_KEYS, ("net income",))
    eps, _n_eps = _pick(q, _EPS_KEYS, ("eps", "per share"))
    picked = f"매출={_n_rev} · 영업이익={_n_opi} · 순이익={_n_ni} · EPS={_n_eps}"
    L = pd.DataFrame(index=q.index)
    L["매출"] = rev if rev is not None else np.nan
    L["영업이익"] = opi if opi is not None else np.nan
    L["순이익"] = ni if ni is not None else np.nan
    L["EPS"] = eps if eps is not None else np.nan
    L = L.sort_index()
    L["기간말"] = L.index
    # ---- 유효일 ----
    lag = pd.Timedelta(days=int(cfg.FUND_PUBLISH_LAG_DAYS))
    eff: List[pd.Timestamp] = []
    src: List[str] = []
    e_idx = (earn.index if isinstance(earn, pd.DataFrame) and len(earn) else pd.DatetimeIndex([]))
    for pe in L.index:
        cand = e_idx[e_idx >= pe]
        if len(cand):
            d = pd.Timestamp(cand[0])
            # 발표일이 기간말보다 150일 넘게 뒤면 짝이 잘못 맞은 것으로 보고 지연 규칙을 쓴다
            if (d - pe).days <= 150:
                eff.append(d); src.append("발표일")
                continue
        eff.append(pd.Timestamp(pe) + lag); src.append(f"기간말+{int(cfg.FUND_PUBLISH_LAG_DAYS)}일")
    L["유효일"] = pd.DatetimeIndex(eff)
    L["유효일 출처"] = src
    L["선택 항목"] = picked          # 어떤 열을 골랐는지 원장에 남긴다(02 시트가 이걸 요약한다)
    # ---- 분기 파생(원장 안에서 계산 — 전부 과거 분기만 쓴다) ----
    L["매출_YoY"] = L["매출"] / L["매출"].shift(4) - 1.0
    L["EPS_YoY"] = L["EPS"] / L["EPS"].shift(4).abs().replace(0, np.nan) - 1.0
    with np.errstate(invalid="ignore", divide="ignore"):
        L["영업이익률"] = L["영업이익"] / L["매출"].replace(0, np.nan)
    L["영업이익률_변화"] = L["영업이익률"] - L["영업이익률"].shift(4)
    L["매출성장_가속"] = L["매출_YoY"] - L["매출_YoY"].shift(1)
    # ---- as-of 조인 ----
    feats = ["매출_YoY", "EPS_YoY", "영업이익률", "영업이익률_변화", "매출성장_가속"]
    LL = L.dropna(subset=["유효일"]).sort_values("유효일")
    base = pd.DataFrame({"날짜": pd.DatetimeIndex(idx)}).sort_values("날짜")
    merged = pd.merge_asof(base, LL[["유효일"] + feats].rename(columns={"유효일": "날짜"}),
                           on="날짜", direction="backward")
    merged = merged.set_index("날짜").reindex(idx)
    merged["펀더멘탈_분기수"] = pd.merge_asof(
        base, pd.DataFrame({"날짜": LL["유효일"].values,
                            "펀더멘탈_분기수": np.arange(1, len(LL) + 1)}).sort_values("날짜"),
        on="날짜", direction="backward").set_index("날짜").reindex(idx)["펀더멘탈_분기수"]
    # 분기 수가 5개 미만인 구간은 YoY를 만들 수 없다 — 값이 있으면 지운다(추정 금지)
    thin = merged["펀더멘탈_분기수"].fillna(0) < 5
    for c in ("매출_YoY", "EPS_YoY", "영업이익률_변화"):
        merged.loc[thin, c] = np.nan
    mh = int(cfg.OWN_PCT_MIN_HIST)
    for c in feats:
        merged[f"{c}_pct"] = _own_pct(merged[c], mh)
    return merged, L


def build_earnings_features(rec: Dict[str, Any], idx: pd.DatetimeIndex, px: pd.Series,
                            cfg: StockConfig) -> Tuple[pd.DataFrame, pd.DataFrame]:
    """[K4] 어닝 이벤트 특성 + 이벤트 원장.
    쓰는 것: **서프라이즈%**(직전 발표), **발표 후 경과일**, 발표일 당일 갭.
    ⚠ '다음 발표까지 남은 일수'는 쓰지 않는다 — 과거 시점에 미래 일정을 알았다고 가정하는 룩어헤드다.
      (yfinance가 주는 예정일은 '오늘' 기준이며 과거에 그 값이 있었다는 보장이 없다.)"""
    out = pd.DataFrame(index=idx)
    for c in ("어닝_서프라이즈%", "어닝_경과일", "어닝_갭%", "어닝_서프라이즈%_pct"):
        out[c] = np.nan
    earn = rec.get("earn")
    ledger = pd.DataFrame()
    if not isinstance(earn, pd.DataFrame) or not len(earn):
        return out, ledger
    e = earn.copy()
    scol = next((c for c in e.columns if "Surprise" in str(c)), None)
    rcol = next((c for c in e.columns if "Reported" in str(c)), None)
    ecol = next((c for c in e.columns if "Estimate" in str(c)), None)
    L = pd.DataFrame(index=e.index)
    L["발표일"] = e.index
    L["예상EPS"] = pd.to_numeric(e[ecol], errors="coerce") if ecol else np.nan
    L["실제EPS"] = pd.to_numeric(e[rcol], errors="coerce") if rcol else np.nan
    L["서프라이즈%"] = pd.to_numeric(e[scol], errors="coerce") if scol else np.nan
    # 발표일이 **과거**인 행만 이벤트로 본다(미래 예정 행은 원장에만 남기고 특성에는 안 쓴다)
    L["과거여부"] = L.index <= (idx[-1] if len(idx) else L.index[-1])
    p = pd.Series(px).reindex(idx).astype(float)
    # 발표일 당일 갭(전일 종가 → 당일 종가) — 발표가 장전/장후인지 모르므로 '당일 수익'으로 근사한다
    day_ret = p.pct_change()
    gaps = {}
    for d in L.index:
        if d in day_ret.index and pd.notna(day_ret.get(d)):
            gaps[d] = float(day_ret.loc[d])
    L["발표일 수익%"] = [100.0 * gaps.get(d, np.nan) for d in L.index]
    # PEAD 창 — 발표 후 1/5/21일 누적 수익(원장 전용 진단. 특성이 아니다)
    for h in (1, 5, 21):
        vals = []
        for d in L.index:
            if d not in p.index:
                vals.append(np.nan); continue
            i = p.index.get_loc(d)
            j = min(i + h, len(p) - 1)
            vals.append(100.0 * float(p.iloc[j] / p.iloc[i] - 1.0) if i < len(p) - 1 else np.nan)
        L[f"발표후{h}일%"] = vals
    ledger = L.reset_index(drop=True)
    past = L[L["과거여부"]].sort_index()
    if len(past):
        base = pd.DataFrame({"날짜": pd.DatetimeIndex(idx)}).sort_values("날짜")
        m = pd.merge_asof(base,
                          pd.DataFrame({"날짜": pd.DatetimeIndex(past.index),
                                        "어닝_서프라이즈%": past["서프라이즈%"].values,
                                        "_last": pd.DatetimeIndex(past.index)}).sort_values("날짜"),
                          on="날짜", direction="backward").set_index("날짜").reindex(idx)
        out["어닝_서프라이즈%"] = m["어닝_서프라이즈%"]
        _last = m["_last"]
        out["어닝_경과일"] = (pd.Series(idx, index=idx) - _last).dt.days
        out["어닝_갭%"] = [100.0 * gaps.get(d, np.nan) if d in gaps else np.nan for d in idx]
        out["어닝_갭%"] = pd.Series(out["어닝_갭%"].values, index=idx).ffill()
        out["어닝_서프라이즈%_pct"] = _own_pct(out["어닝_서프라이즈%"], int(cfg.OWN_PCT_MIN_HIST))
    return out, ledger


def build_earnings_fundamentals(rec: Dict[str, Any], idx: pd.DatetimeIndex, cfg: StockConfig
                                ) -> pd.DataFrame:
    """[K1 ★ v0.2.0 신규] **어닝 원장의 실제 EPS로** 펀더멘탈 성장 특성을 만든다.

    왜 이것이 필요한가(v0.1.0 첫 실행의 결함):
      yfinance의 quarterly_income_stmt는 **최근 5~6분기**만 준다(02 시트 '펀더멘탈 분기수' 5~7).
      YoY는 4분기 전과 비교하므로 거의 전부 NaN이 되고, 그래서 03 시트 B블록에 F 계열이
      **1종목**밖에 등장하지 못했다 — '효과 없음'이 아니라 **측정 불가**였다.
      반면 get_earnings_dates()는 **실제 발표일 + 실제 EPS + 서프라이즈를 25년치**(티커당 58~100분기) 준다.

    ★ 인과: 색인이 **실제 발표일**이므로 as-of(발표일 ≤ t) 조인만으로 보장된다. 기간말 추정이 필요 없다 —
      quarterly 재무제표보다 오히려 안전하다.
    ⚠ EPS 부호가 바뀌는 구간(적자→흑자)에서 YoY는 무의미하다. 분모에 abs()를 쓰고
      **|기준 EPS| < 0.01이면 NaN**으로 둔다(추정하지 않는다).
    ⚠ 4분기 합(TTM) YoY도 함께 만든다 — 계절성이 큰 종목(소매·항공)에서 단일 분기 YoY보다 안정적이다."""
    out = pd.DataFrame(index=idx)
    cols = ["EPS_YoY_E", "EPS_가속_E", "EPS_TTM_YoY_E", "서프라이즈_4분기평균", "서프라이즈_연속음수"]
    for c in cols:
        out[c] = np.nan
    earn = rec.get("earn")
    if not isinstance(earn, pd.DataFrame) or not len(earn):
        return out
    e = earn.copy()
    e.index = pd.to_datetime(e.index, errors="coerce")
    e = e[e.index.notna()].sort_index()
    rcol = next((c for c in e.columns if "Reported" in str(c)), None)
    scol = next((c for c in e.columns if "Surprise" in str(c)), None)
    if rcol is None:
        return out
    L = pd.DataFrame(index=e.index)
    L["eps"] = pd.to_numeric(e[rcol], errors="coerce")
    L["sur"] = pd.to_numeric(e[scol], errors="coerce") if scol else np.nan
    # 발표일이 **미래**인 행(다음 예정 실적)은 특성에서 제외한다 — 과거에 알 수 없었다.
    L = L[L.index <= (idx[-1] if len(idx) else L.index[-1])]
    L = L[L["eps"].notna()]
    if len(L) < 6:
        return out
    base = L["eps"].shift(4)
    denom = base.abs()
    L["EPS_YoY_E"] = (L["eps"] - base) / denom.where(denom >= 0.01)
    L["EPS_가속_E"] = L["EPS_YoY_E"] - L["EPS_YoY_E"].shift(1)
    ttm = L["eps"].rolling(4, min_periods=4).sum()
    tbase = ttm.shift(4)
    tden = tbase.abs()
    L["EPS_TTM_YoY_E"] = (ttm - tbase) / tden.where(tden >= 0.04)
    L["서프라이즈_4분기평균"] = L["sur"].rolling(4, min_periods=2).mean()
    _neg = (L["sur"] < 0).astype(float)
    # 연속 음수 카운트(직전까지) — 누적합 차이로 만든다(그날까지의 정보만)
    _grp = (_neg == 0).cumsum()
    L["서프라이즈_연속음수"] = _neg.groupby(_grp).cumsum()
    keep = [c for c in cols if c in L.columns]
    LL = L[keep].copy()
    LL["날짜"] = LL.index
    base_df = pd.DataFrame({"날짜": pd.DatetimeIndex(idx)}).sort_values("날짜")
    m = pd.merge_asof(base_df, LL.sort_values("날짜"), on="날짜", direction="backward")
    m = m.set_index("날짜").reindex(idx)
    for c in keep:
        out[c] = m[c]
    mh = int(cfg.OWN_PCT_MIN_HIST)
    for c in ("EPS_YoY_E", "EPS_TTM_YoY_E", "서프라이즈_4분기평균"):
        out[f"{c}_pct"] = _own_pct(out[c], mh)
    return out


# =============================================================================
# [3] 예측 규칙 · 소수 클래스 채점
#     ⚠ v0.1.0에서 라이브는 ext200 하나뿐이다. 나머지는 전부 **후보**이고 03 시트가 채점만 한다.
# =============================================================================
def _fwd_ret(px: pd.Series, h: int) -> pd.Series:
    """t일 확정 → t+1 시가 체결 관행에 맞춘 향후 h일 수익(M·S·I와 같은 정의)."""
    p = pd.Series(px).astype(float)
    return p.shift(-(h + 1)) / p.shift(-1) - 1.0


def _minority(pred: pd.Series, real: pd.Series) -> Dict[str, Any]:
    """소수 클래스 잣대 — 정밀도는 **반드시 기저율과 함께** 본다."""
    p = pd.Series(pred).astype(bool)
    y = pd.Series(real).astype(bool)
    m = p.index.intersection(y.index)
    p, y = p.loc[m], y.loc[m]
    tp = int((p & y).sum()); fp = int((p & ~y).sum())
    tn = int((~p & ~y).sum()); fn = int((~p & y).sum())
    den = float((tp + fp) * (tp + fn) * (tn + fp) * (tn + fn))
    rec = tp / (tp + fn) if (tp + fn) else np.nan
    spc = tn / (tn + fp) if (tn + fp) else np.nan
    return {"n": len(p), "n_pred": int(p.sum()), "base": (float(y.mean()) if len(y) else np.nan),
            "prec": (tp / (tp + fp) if (tp + fp) else np.nan), "rec": rec,
            "bal": (0.5 * (rec + spc) if pd.notna(rec) and pd.notna(spc) else np.nan),
            "mcc": ((tp * tn - fp * fn) / math.sqrt(den) if den > 0 else np.nan)}


def _yearly_kn(pred: pd.Series, real: pd.Series, min_days: int = 40) -> Tuple[int, int]:
    """연도별 '정밀도 > 기저' 횟수 — 1급 판정 지표(풀샘플 단독 금지)."""
    df = pd.DataFrame({"p": pd.Series(pred).astype(bool), "y": pd.Series(real).astype(bool)}).dropna()
    w = n = 0
    for _, g in df.groupby(df.index.year):
        if len(g) < min_days or not bool(g["p"].any()):
            continue
        n += 1
        w += int(float(g.loc[g["p"], "y"].mean()) > float(g["y"].mean()))
    return w, n


def rule_matrix(feat: pd.DataFrame, cfg: StockConfig) -> Dict[str, pd.Series]:
    """예측 규칙 후보 — **하락**을 맞추려는 규칙 집합(사용자 요구가 하락 정확도다).
    각 규칙은 '앞으로 내릴 것 같다 = True'를 뜻한다. 전부 t일까지의 정보다.

    가격 후보(P)는 I 계층에서 이미 측정된 것을 이식한다 — 특히 **vol21 하위 1/3**은
    I의 13p A3에서 정밀−기저 +0.14를 낸 유일한 산업별 하락 신호였다.
    펀더멘탈·어닝 후보(F·E)가 이 파일의 새로운 부분이다."""
    R: Dict[str, pd.Series] = {}
    g = lambda c: (pd.to_numeric(feat[c], errors="coerce") if c in feat.columns
                   else pd.Series(np.nan, index=feat.index))
    # ---- 가격 ----
    R["P1 200일선 아래"] = g("ext200") < 0
    R["P2 vol21 자기이력 하위1/3"] = g("vol21_pct") <= 1.0 / 3.0
    R["P3 vol21 자기이력 상위1/5"] = g("vol21_pct") >= 0.8
    R["P4 mom63 하위1/3"] = g("mom63_pct") <= 1.0 / 3.0
    R["P5 park5 상위1/5"] = g("park5_pct") >= 0.8
    R["P6 P1 & P2"] = (g("ext200") < 0) & (g("vol21_pct") <= 1.0 / 3.0)
    # ---- 펀더멘탈 ----
    R["F1 매출 YoY < 0"] = g("매출_YoY") < 0
    R["F2 EPS YoY < 0"] = g("EPS_YoY") < 0
    R["F3 영업이익률 4분기 악화"] = g("영업이익률_변화") < 0
    R["F4 매출성장 감속"] = g("매출성장_가속") < 0
    R["F5 F1 & F3"] = (g("매출_YoY") < 0) & (g("영업이익률_변화") < 0)
    R["F6 P1 & F1(추세+펀더)"] = (g("ext200") < 0) & (g("매출_YoY") < 0)
    # ---- 어닝 ----
    R["E1 직전 서프라이즈 < 0"] = g("어닝_서프라이즈%") < 0
    R["E2 서프라이즈 자기이력 하위1/3"] = g("어닝_서프라이즈%_pct") <= 1.0 / 3.0
    R["E3 발표 후 21일 이내 & 서프라이즈<0"] = (g("어닝_경과일") <= 21) & (g("어닝_서프라이즈%") < 0)
    R["E4 발표일 수익 < −3%"] = g("어닝_갭%") < -3.0
    R["E5 E1 & P1"] = (g("어닝_서프라이즈%") < 0) & (g("ext200") < 0)
    R["E6 E1 & F1"] = (g("어닝_서프라이즈%") < 0) & (g("매출_YoY") < 0)
    # ---- [v0.2.0 K3] 빠른 방어 후보 — "200일선은 양쪽에서 다 늦다"는 진단의 직접 대응 ----
    #   19 시트 실측: 상승구간 786개 중 미참여 190개 · 중위 대응 지연 **12.5거래일**.
    #   하락에서도 TSLA 2020-03(−51.8%, 10거래일)은 200일선이 반응할 시간이 아예 없었다.
    #   그래서 **더 짧은 창**의 후보를 넣는다. ⚠ 라이브가 아니라 03 시트 채점용이다.
    R["P7 20일선 아래"] = g("ma20_ext") < 0
    R["P8 5일수익 하위10%"] = g("ret5_pct") <= 0.10
    R["P9 낙폭 −10% 돌파"] = g("dd63") <= -0.10
    R["P10 ATR 트레일링 이탈"] = g("atr_trail_break") > 0
    R["P11 20일선 하향교차 당일"] = g("ma20_cross_dn") > 0
    R["P12 P7 & P2"] = (g("ma20_ext") < 0) & (g("vol21_pct") <= 1.0 / 3.0)
    # ---- [v0.2.0 K1] 어닝 기반 펀더멘탈 후보 — quarterly 재무제표(5분기)로는 측정 불가였던 것 ----
    R["G1 EPS YoY(어닝) < 0"] = g("EPS_YoY_E") < 0
    R["G2 EPS TTM YoY(어닝) < 0"] = g("EPS_TTM_YoY_E") < 0
    R["G3 EPS 성장 감속(어닝)"] = g("EPS_가속_E") < 0
    R["G4 서프라이즈 4분기평균 < 0"] = g("서프라이즈_4분기평균") < 0
    R["G5 서프라이즈 2회 연속 음수"] = g("서프라이즈_연속음수") >= 2
    R["G6 G2 & P2"] = (g("EPS_TTM_YoY_E") < 0) & (g("vol21_pct") <= 1.0 / 3.0)
    return {k: pd.Series(v).astype("boolean") for k, v in R.items()}


def build_rule_accuracy(panel: Dict[str, pd.DataFrame], cfg: StockConfig) -> pd.DataFrame:
    """[03_예측규칙정확도] 규칙 × 티커 × 지평의 소수 클래스 표 + 규칙별 29종목 집계.
    '정밀도'는 늘 '기저 실현하락률'과 같은 행에 있다(사용자 규칙 1)."""
    rows: List[dict] = []
    rows.append({"블록": "── 읽는 법 ──", "규칙": "",
                 "판독": ("각 규칙은 '앞으로 내릴 것 같다'를 뜻한다. **정밀도를 반드시 같은 행의 "
                        "'기저 실현하락률'과 비교**할 것 — 기저보다 높아야 예측력이 있다. 판정은 "
                        "**연도 k/n**으로 한다(풀샘플은 상관 높은 29계열을 한 덩어리로 세어 부풀려진다). "
                        "P는 가격(I 계층에서 이식), F는 펀더멘탈, E는 어닝 후보다. "
                        "⚠ v0.1.0에서 라이브는 P1(200일선)만이고 나머지는 전부 후보다 — "
                        "승격은 연도 k/n과 대조군을 갖춘 다음 라운드의 일이다.")})
    agg: Dict[Tuple[str, int], Dict[str, List[float]]] = {}
    for t, feat in panel.items():
        rules = rule_matrix(feat, cfg)
        px = pd.to_numeric(feat["종가"], errors="coerce")
        for h in cfg.HORIZONS:
            fwd = _fwd_ret(px, int(h))
            real = (fwd < 0)
            ok = fwd.notna()
            for name, pr in rules.items():
                p = pr.reindex(feat.index).fillna(False).astype(bool) & ok
                if int(p.sum()) < 20:
                    continue
                m = _minority(p[ok], real[ok])
                w, n = _yearly_kn(p[ok], real[ok])
                gap = (float(fwd[ok & p].mean()) - float(fwd[ok & ~p].mean())) if int(p.sum()) else np.nan
                rows.append({"블록": "A. 티커별", "규칙": name, "티커": t,
                             "이름": STOCK_NAME_KR.get(t, ""), "지평(일)": int(h),
                             "예측일수": m["n_pred"], "표본일수": m["n"],
                             "기저 실현하락률": round(m["base"], 4),
                             "하락 정밀도": (round(m["prec"], 4) if pd.notna(m["prec"]) else None),
                             "정밀−기저": (round(m["prec"] - m["base"], 4)
                                       if pd.notna(m["prec"]) and pd.notna(m["base"]) else None),
                             "하락 재현율": (round(m["rec"], 4) if pd.notna(m["rec"]) else None),
                             "균형정확도": (round(m["bal"], 4) if pd.notna(m["bal"]) else None),
                             "MCC": (round(m["mcc"], 4) if pd.notna(m["mcc"]) else None),
                             "연도 정밀도>기저": f"{w}/{n}",
                             "연도비율": (round(w / n, 3) if n else None),
                             "향후수익 격차(%p)": (round(gap * 100, 3) if pd.notna(gap) else None)})
                k = (name, int(h))
                a = agg.setdefault(k, {"pmb": [], "base": [], "prec": [], "w": [], "n": [],
                                       "mcc": [], "np": [], "gap": []})
                if pd.notna(m["prec"]) and pd.notna(m["base"]):
                    a["pmb"].append(m["prec"] - m["base"])
                a["base"].append(m["base"]); a["prec"].append(m["prec"])
                a["w"].append(w); a["n"].append(n); a["mcc"].append(m["mcc"])
                a["np"].append(m["n_pred"])
                if pd.notna(gap):
                    a["gap"].append(gap)
    for (name, h), a in sorted(agg.items(), key=lambda x: (x[0][1], x[0][0])):
        if not a["pmb"]:
            continue
        w, n = int(np.nansum(a["w"])), int(np.nansum(a["n"]))
        rows.append({"블록": "B. 규칙별 29종목 집계", "규칙": name, "티커": f"{len(a['pmb'])}종목",
                     "지평(일)": int(h), "예측일수": int(np.nanmean(a["np"])),
                     "기저 실현하락률": round(float(np.nanmean(a["base"])), 4),
                     "하락 정밀도": round(float(np.nanmean(a["prec"])), 4),
                     "정밀−기저": round(float(np.nanmean(a["pmb"])), 4),
                     "MCC": round(float(np.nanmean(a["mcc"])), 4),
                     "정밀>기저 종목": f"{int(sum(1 for v in a['pmb'] if v > 0))}/{len(a['pmb'])}",
                     "연도 정밀도>기저": f"{w}/{n}",
                     "연도비율": (round(w / n, 3) if n else None),
                     "향후수익 격차(%p)": (round(float(np.nanmean(a["gap"])) * 100, 3) if a["gap"] else None)})
    rows.append({"블록": "── 판정(사전등록) ──", "규칙": "",
                 "판독": ("v0.2.0 승격 조건 — 후보가 **셋을 동시에** 만족해야 라이브에 올린다: "
                        "(1) B블록 연도비율 ≥ 0.60  (2) 정밀>기저 종목 ≥ 20/29  "
                        "(3) 향후수익 격차 < 0(경고일의 실제 수익이 더 낮아야 쓸 값이 있다). "
                        "⚠ 연구·교육용이며 투자 조언이 아니다.")})
    return pd.DataFrame(rows)


# =============================================================================
# [4] 라이브 규칙 · 목표비중
# =============================================================================
def build_positions(feat: pd.DataFrame, cfg: StockConfig,
                    rule: Optional[str] = None, cut_weight: Optional[float] = None,
                    cut_rules: Optional[Tuple[str, ...]] = None,
                    calendar_control: bool = False,
                    cut_min_agree: Optional[int] = None,
                    ticker: str = "",
                    market_w: Optional[pd.Series] = None) -> pd.DataFrame:
    """[K2 ★ v0.2.0] 목표비중. 체결 규칙은 M·S·I와 같다 — t일 확정, t+1일 집행(exec_w(t)=target_w(t−1)).

    규칙 3종:
      "base1_cut" (라이브) — **기본 1.0**에서 시작해 CUT_RULES의 하락 신호가 켜진 날만 CUT_WEIGHT로 감축.
        사용자 요구("상승을 타서 비중 최대로")를 기본값으로 삼고, **측정상 값이 있는 신호로만** 깎는다.
      "ext200"    (v0.1.0) — 200일선 위 1 / 아래 0. ⚠ 03 시트 측정에서 정밀−기저 −0.0198로 **반대 방향**이었다.
      "always"    (대조군) — 항상 1.0 = 사실상 B&H. 격자의 기준선이다.

      "m_only"    (v0.4.0 격자) — 기본 1.0에 감축 규칙 없음(시장 예산만 — market_w가 있어야 의미가 있다).

    market_w [v0.4.0 R77 ★★]: M의 목표비중 E_t(t일 확정, 날짜 인덱스). 주면 **목표비중 = min(규칙 비중, E_t)**.
      E_t는 종목 거래일로 reindex 후 ffill만(직전 확정값 — 미래값 없음). E_t가 없는 날(M 이력 이전)은 규칙 비중 그대로.
      "always"(B&H 대조군)에는 적용하지 않는다.
    calendar_control=True면 **같은 감축 일수만큼 신호 없이 균등 간격으로** 감축한다(달력 대조군).
      이게 있어야 "신호가 좋은 날을 골랐나"와 "그냥 노출을 줄여 MDD가 좋아졌나"를 가른다 —
      I 계층에서 이 대조군이 세 번 설계를 살렸다(v0.15.0 브레이크·v0.16.0 경고격자·v0.18.0 확신캡).
    """
    out = pd.DataFrame(index=feat.index)
    rule = str(rule if rule is not None else getattr(cfg, "LIVE_RULE", "base1_cut")).lower()
    cw = float(cut_weight if cut_weight is not None else getattr(cfg, "CUT_WEIGHT", 0.0))
    ext = pd.to_numeric(feat.get("ext200"), errors="coerce")
    if rule == "always":
        tgt = pd.Series(1.0, index=feat.index)
        state = pd.Series("보유(항상 1.0)", index=feat.index)
    elif rule == "m_only":
        tgt = pd.Series(1.0, index=feat.index)
        state = pd.Series("보유", index=feat.index)
    elif rule == "ext200":
        up = (ext > 0)
        tgt = up.astype(float).where(ext.notna(), np.nan).ffill().fillna(0.0)
        state = pd.Series(np.where(up.fillna(False), "상승", "하락"), index=feat.index)
    else:   # base1_cut
        names = tuple(cut_rules if cut_rules is not None
                      else getattr(cfg, "CUT_RULES", ()) or ())
        agree = int(cut_min_agree if cut_min_agree is not None
                    else getattr(cfg, "CUT_MIN_AGREE", 1))
        agree = max(1, min(agree, max(1, len(names))))
        R = rule_matrix(feat, cfg)
        # ★ v0.2.1 — OR 대신 **동의 개수**로 센다. agree=1이면 OR과 동일하다.
        #   왜 바뀌었나: 분위 버킷 규칙(하위 1/3)은 정의상 33%의 날에 점화되므로 OR로 3개를 묶으면
        #   약 60%의 날을 잘라 평균노출이 0.49까지 떨어졌다 — 대체하려던 ext200(0.59)보다 낮았다.
        #   점화 빈도를 **규칙마다 로그로 남긴다** — 다음에 같은 실수를 반복하지 않기 위해서다.
        votes = pd.Series(0, index=feat.index, dtype=int)
        used: List[str] = []; missing: List[str] = []; freqs: List[str] = []
        for nm in names:
            if nm in R:
                _b = R[nm].reindex(feat.index).fillna(False).astype(bool)
                votes = votes + _b.astype(int)
                used.append(nm); freqs.append(f"{str(nm).split()[0]}={float(_b.mean()):.3f}")
            else:
                missing.append(nm)
        cut = (votes >= agree)
        if missing:
            log("POS", kv(event="cut_rule_not_found", ticker=ticker,
                           missing=";".join(missing),
                           suggest="rule_matrix의 키와 CUT_RULES의 문자열이 정확히 같아야 한다"),
                level="warning")
        if not used:
            log("POS", kv(event="cut_rules_empty", ticker=ticker,
                           note="감축 규칙이 하나도 적용되지 않아 비중이 항상 1.0이다(= B&H)"),
                level="warning")
        log("POS", kv(event="cut_signal", ticker=ticker, rules=len(used), min_agree=agree,
                       fire_rate=round(float(cut.mean()), 4), per_rule=";".join(freqs),
                       calendar_control=int(bool(calendar_control)),
                       note="fire_rate가 0.3을 넘으면 '이벤트'가 아니라 상태 배분기다 — 라이브 부적격"),
            level="debug")
        if calendar_control:
            # 같은 날수를 신호 없이 균등 간격으로 — 난수 없음(재현 가능)
            k = int(cut.sum())
            cal = pd.Series(False, index=feat.index)
            if 0 < k < len(feat):
                pos = np.unique(np.linspace(0, len(feat) - 1, num=k, dtype=int))
                cal.iloc[pos] = True
            cut = cal
        tgt = pd.Series(1.0, index=feat.index).where(~cut, cw)
        state = pd.Series(np.where(cut, "감축", "보유"), index=feat.index)
        out["감축신호"] = cut.astype(int)
        out["감축득표"] = votes.astype(int)       # 몇 개 규칙이 동의했는가(감사용)
        # ★ 노출 하한 감시 — 자동으로 값을 바꾸지 않는다(리스크 파라미터를 조용히 건드리지 않기 위해).
        #   ★ **라이브 설정에만** 경고한다(cut_rules/cut_min_agree를 명시한 호출은 격자다).
        #     격자 행은 일부러 나쁜 설정을 검정하는 것이므로 경고하면 로그가 무의미해진다 —
        #     실제로 첫 실행에서 격자의 '3규칙 OR' 행이 티커마다 경고를 뿜어 라이브 경고를 묻었다.
        _fl = float(getattr(cfg, "CUT_EXPOSURE_FLOOR_WARN", 0.0))
        _mx = float(tgt.mean())
        _is_live = (cut_rules is None and cut_min_agree is None and not calendar_control)
        if _fl > 0.0 and _mx < _fl and _is_live:
            log("POS", kv(event="exposure_below_floor", ticker=ticker,
                           mean_target_w=round(_mx, 4), floor=_fl,
                           fire_rate=round(float(cut.mean()), 4), min_agree=agree,
                           suggest=("CUT_MIN_AGREE를 올리거나 분위 버킷 규칙(하위 1/3 계열)을 "
                                    "CUT_RULES에서 빼고 이벤트형 규칙만 남길 것 — "
                                    "사용자 요구는 '상승을 타서 비중 최대로'다")),
                level="warning")
    # ---- [v0.4.0 R77 ★★ 위험 파라미터] 시장 예산(M E_t) — 목표비중 = min(규칙 비중, E_t) ----
    if market_w is not None and rule != "always":
        _E = pd.to_numeric(pd.Series(market_w), errors="coerce")
        _E.index = pd.DatetimeIndex(_E.index)
        _E = _E[~_E.index.duplicated(keep="last")].sort_index()
        _E = _E.reindex(_E.index.union(feat.index)).ffill().reindex(feat.index).clip(0.0, 1.0)
        _has = _E.notna()
        _pre = tgt.copy()
        tgt = pd.Series(np.where(_has, np.minimum(_pre.values, _E.fillna(1.0).values), _pre.values), index=feat.index)
        _mcut = _has & (_E <= 1e-9) & (_pre > 1e-9)
        _mpart = _has & (_E > 1e-9) & (_E < 1.0 - 1e-9) & (_pre > 1e-9)
        state = pd.Series(np.where(_mcut, "시장컷(M E_t=0)", np.where(_mpart, "시장부분(M)", state.astype(str))),
                          index=feat.index)
        out["시장예산(M E_t)"] = _E
        log("POS", kv(event="market_budget_applied", ticker=ticker, rule=rule,
                       days=int(len(feat)), no_budget_days=int((~_has).sum()),
                       market_cut_days=int(_mcut.sum()), market_partial_days=int(_mpart.sum()),
                       mean_w_before=round(float(_pre.mean()), 4), mean_w_after=round(float(tgt.mean()), 4)),
            level="debug")
    out["확정국면"] = state
    out["목표비중"] = tgt
    out["집행비중"] = tgt.shift(1).fillna(0.0)
    out["전략일간수익"] = out["집행비중"] * pd.to_numeric(feat["일간수익"], errors="coerce").fillna(0.0)
    return out


# =============================================================================
# [4a2] ★★ v0.7.0 R80 신규 — I 계층 산업/섹터 비중 출처 결정
#   사용자 지시(2026-09-21): "주식도 똑같이 산업 비중을 참고해서 해야해".
#   runner는 고치지 않는다(사용자 지시). 그래서 K가 스스로 찾는다 — R77 시장예산 통로와 같은 방식:
#     (1) I 모듈 통로 industry_alloc_handoff() — I.run()이 I★ 배분(산업비중 + 부모ETF 잔여다리)를 남긴다
#     (2) run(parent_w=…) 인자(날짜×산업ETF) — 잔여 다리가 없으므로 산업비중만 쓴다
#     (3) 없으면 None → 배분은 1/N 고정슬리브(v0.6.0)로 되돌아가고 00시트에 그 사실을 적는다
#   ⚠ 룩어헤드 없음: I가 t일 종가로 확정한 목표비중을 그대로 받고, 체결 지연(t+1)은 build_allocation의
#     exec_w = target_w.shift(1)이 그대로 적용한다(M·S·I와 같은 규칙).
# =============================================================================
def _resolve_industry_alloc(cfg: StockConfig, parent_w: Optional[pd.DataFrame] = None
                            ) -> Tuple[Optional[Dict[str, Any]], Dict[str, Any]]:
    """I★ 배분(산업 비중·부모 잔여 다리·산업→섹터 맵)을 찾아 돌려준다. 새 계산은 하지 않는다(사본만)."""
    info: Dict[str, Any] = {"source": "-", "asof": "-", "industries": 0, "parents": 0, "ok": False, "note": ""}
    H: Optional[Dict[str, Any]] = None
    for _nm, _mod in list(sys.modules.items()):
        try:
            _fn = getattr(_mod, "industry_alloc_handoff", None)
        except Exception:
            continue
        if callable(_fn):
            try:
                _h = _fn()
            except Exception as _e:
                log("ALLOC", kv(event="industry_handoff_read_failed", module=_nm, err=type(_e).__name__),
                    level="warning")
                continue
            if isinstance(_h, dict) and isinstance(_h.get("industry_w"), pd.DataFrame) and len(_h["industry_w"]):
                H = dict(_h)
                info["source"] = f"I 모듈 통로({_nm}.industry_alloc_handoff · {str(_h.get('label', '-'))[:40]})"
                break
    if H is None and parent_w is not None and len(parent_w):
        H = {"industry_w": pd.DataFrame(parent_w).copy(), "parent_w": pd.DataFrame(index=pd.DataFrame(parent_w).index),
             "parent_of": {}, "label": "run(parent_w=…) 인자"}
        info["source"] = "run(parent_w=…) 인자(산업비중만 · 부모 잔여다리 없음)"
    if H is None:
        info["note"] = "⚠ I 산업비중 출처 없음 — 1/N 고정슬리브(v0.6.0)로 돌린다"
        log("ALLOC", kv(event="industry_alloc_missing", fallback="equal_fixed",
                        next_step="run_pipeline.main()으로 I와 함께 돌리면 산업 연동이 살아난다"),
            level="warning")
        return None, info
    iw = pd.DataFrame(H.get("industry_w")).apply(pd.to_numeric, errors="coerce")
    iw.index = pd.DatetimeIndex(iw.index)
    iw = iw[~iw.index.duplicated(keep="last")].sort_index().fillna(0.0).clip(lower=0.0)
    pw = H.get("parent_w")
    pw = (pd.DataFrame(pw).apply(pd.to_numeric, errors="coerce") if isinstance(pw, pd.DataFrame)
          else pd.DataFrame(index=iw.index))
    if len(pw):
        pw.index = pd.DatetimeIndex(pw.index)
        pw = pw[~pw.index.duplicated(keep="last")].sort_index().fillna(0.0).clip(lower=0.0)
    info.update({"asof": (str(iw.index[-1].date()) if len(iw) else "-"), "industries": int(iw.shape[1]),
                 "parents": int(pw.shape[1]), "ok": True,
                 "note": "적용 — 배분 형태에만 쓴다(총노출은 1/N 규칙과 동일)"})
    log("ALLOC", kv(event="industry_alloc_resolved", source=str(info["source"])[:80],
                    industries=info["industries"], parents=info["parents"], asof=info["asof"],
                    rows=int(len(iw)), mean_ind_sum=round(float(iw.sum(axis=1).mean()), 4),
                    mean_par_sum=(round(float(pw.sum(axis=1).mean()), 4) if len(pw) else None)))
    _cs = H.get("coupling_score")
    if isinstance(_cs, pd.DataFrame) and len(_cs):
        _cs = _cs.apply(pd.to_numeric, errors="coerce")
        _cs.index = pd.DatetimeIndex(_cs.index)
        _cs = _cs[~_cs.index.duplicated(keep="last")].sort_index().clip(0.0, 1.0)
        info["coupling_cols"] = int(_cs.shape[1])
    else:
        _cs = None
        info["coupling_cols"] = 0
    return {"industry_w": iw, "parent_w": pw, "ind2sec": dict(H.get("parent_of") or {}),
            "coupling_score": _cs, "label": str(H.get("label", "-"))}, info


def _industry_tilt_weights(solo: pd.DataFrame, live: pd.DataFrame, idx: pd.DatetimeIndex,
                           tickers: List[str], cfg: StockConfig, ia: Dict[str, Any],
                           parent_of: Dict[str, str], lam: float, cap: float, source: str,
                           min_cover: float, perm: Optional[np.ndarray] = None
                           ) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    """[v0.7.0 R80] **1/N 고정슬리브의 총노출은 그대로 두고**, 그 노출을 산업/섹터 비중을 참고해 종목 간에 다시 나눈다.

    단계: (1) 기준 형태 = 그날 담을 수 있는 비율 elig/N (감축·미관측 종목은 0 — v0.6.0과 같다)
          (2) 연동 형태 = 그 종목의 부모 산업ETF 비중 + 그 섹터 부모ETF 잔여다리를 섹터 소속 종목에 균등 분배
             (source="sector"면 산업층을 거치지 않고 그 섹터 몫 전체를 섹터 종목에 균등 분배)
          (3) 형태 = (1−λ)·(1) + λ·(2) — 그날 합으로 정규화 → **1/N 규칙의 그날 총노출**로 스케일
          (4) 종목 상한 cap — 넘친 몴은 같은 날 다른 종목의 남은 자리에 재분배(3회 반복 후 남으면 포기=현금)
          (5) 연동을 받은 종목 비율이 min_cover 미만인 날은 그날만 연동을 끄고 1/N 형태를 쓴다(자료 부족 방어)

    perm: 무작위 대조군용 열 순열(산업비중을 종목에 무작위로 배정) — 라이브는 None.
    ⚠ 룩어헤드 없음: I가 t일에 확정한 비중과 그날 확정된 단독 신호만 쓴다. reindex는 ffill만 한다(bfill 금지)."""
    n = max(1, len(tickers))
    elig = solo.fillna(0.0).clip(lower=0.0, upper=1.0).where(live, 0.0)
    base = elig / float(n)                      # (1) v0.6.0 라이브 형태 결 총노출의 정의
    tot_eq = base.sum(axis=1)                   # ★ 바꾸지 않는 것 — 방어는 여기 그대로 남는다
    iw = ia["industry_w"].reindex(idx.union(ia["industry_w"].index)).sort_index().ffill().reindex(idx).fillna(0.0)
    pwd = ia.get("parent_w")
    pw = (pwd.reindex(idx.union(pwd.index)).sort_index().ffill().reindex(idx).fillna(0.0)
          if isinstance(pwd, pd.DataFrame) and len(pwd) and pwd.shape[1] else pd.DataFrame(index=idx))
    ind2sec = dict(ia.get("ind2sec") or {})
    t2i = {t: str(parent_of.get(t, "") or "") for t in tickers}
    t2s = {t: str(ind2sec.get(t2i[t], "") or "") for t in tickers}
    LINK = pd.DataFrame(0.0, index=idx, columns=tickers)
    if str(source).lower() == "sector":
        for sec in sorted({v for v in t2s.values() if v}):
            cols_s = [c for c in iw.columns if str(ind2sec.get(c, "")) == sec]
            v = (iw[cols_s].sum(axis=1) if cols_s else pd.Series(0.0, index=idx))
            if sec in pw.columns:
                v = v + pw[sec]
            mem = [t for t in tickers if t2s[t] == sec]
            if mem:
                LINK[mem] = LINK[mem].add(v / float(len(mem)), axis=0)
    else:
        for t in tickers:
            if t2i[t] and t2i[t] in iw.columns:
                LINK[t] = iw[t2i[t]].values
        for sec in sorted({v for v in t2s.values() if v}):
            if sec in pw.columns:
                mem = [t for t in tickers if t2s[t] == sec]
                if mem:
                    LINK[mem] = LINK[mem].add(pw[sec] / float(len(mem)), axis=0)
    if perm is not None:                        # 무작위 대조군 — 같은 형태의 집중도에서 매핑만 무작위로
        LINK = pd.DataFrame(LINK.values[:, np.asarray(perm)], index=idx, columns=tickers)
    LINK = LINK.clip(lower=0.0).mul(elig)       # 감축·미관측 종목은 연동에서도 0
    n_elig = (elig > 1e-9).sum(axis=1)
    cover = (LINK > 1e-12).sum(axis=1).div(n_elig.replace(0, np.nan))
    thin = (n_elig > 0) & (cover.fillna(0.0) < float(min_cover))     # (5) 자료 부족일
    lam_row = pd.Series(float(lam), index=idx).where(~thin, 0.0)
    S = base.mul(1.0 - lam_row, axis=0) + LINK.mul(lam_row, axis=0)  # (3) 형태
    W = S.div(S.sum(axis=1).replace(0.0, np.nan), axis=0).fillna(0.0).mul(tot_eq, axis=0)
    #   ★ 상한은 **그날 담아야 하는 평균 비중(총노출/적격종목수)** 밑으로 내려갈 수 없다. 그보다 낮으면 재분배해도
    #     담을 자리가 없어 총노출이 줄고(=현금이 늘고) '총노출 불변'이 깨진다 — equal_fixed의 상한 완화와 같은 이유다.
    #     (합성 4종목 시험이 이것을 잡았다: 상한 10% × 4종목 = 0.4 < 1.0이라 노출의 60%가 사라졌다.)
    #     라이브(28종목·평균 총노출 0.53)에서는 평균 비중이 1/28≈0.036이라 상한 10%가 걸리지 않는다 — 이 완화는 안전장치다.
    cap_in = float(cap)
    cap_row = pd.Series(cap_in, index=idx).clip(
        lower=(tot_eq / n_elig.replace(0, np.nan)).fillna(cap_in))
    cap_lift_days = int((cap_row > cap_in + 1e-12).sum())
    rounds = 0
    for _ in range(3):                                               # (4) 상한 + 같은 날 재분배
        over = (W.sub(cap_row, axis=0)).clip(lower=0.0)
        if float(over.values.sum()) < 1e-12:
            break
        rounds += 1
        W = W.clip(upper=cap_row, axis=0)
        room = ((-W).add(cap_row, axis=0)).clip(lower=0.0) * (S > 0)
        add = room.div(room.sum(axis=1).replace(0.0, np.nan), axis=0).mul(over.sum(axis=1), axis=0).fillna(0.0)
        W = W + add
    W = W.clip(lower=0.0).clip(upper=cap_row, axis=0)
    diag = {"lam": float(lam), "cap": cap_in, "cap_set": cap_in, "cap_lift_days": cap_lift_days,
            "cap_max_used": round(float(cap_row.max()), 6), "source": str(source), "min_cover": float(min_cover),
            "thin_days": int(thin.sum()), "cover_mean": (round(float(cover.mean()), 4) if len(cover.dropna()) else None),
            "redistribute_rounds": rounds,
            "tot_gap_max": round(float((W.sum(axis=1) - tot_eq).abs().max()), 8),
            "label": str(ia.get("label", "-"))}
    if cap_lift_days:
        log("ALLOC", kv(event="tilt_cap_lifted", cap_set=cap_in, cap_max_used=round(float(cap_row.max()), 6),
                        days=cap_lift_days, n=n,
                        note="상한이 그날 평균 비중보다 낮은 날만 그날치로 올린다 — 총노출 불변을 지키는 안전장치"))
    if diag["tot_gap_max"] > 1e-6:
        log("ALLOC", kv(event="tilt_total_exposure_drift", gap=diag["tot_gap_max"],
                        note="상한 재분배 후에도 담지 못한 몴이 있다 — 그만큼 현금(의도된 동작·상한의 성질)"))
    return W, diag


def _prob_tilt_weights(solo: pd.DataFrame, live: pd.DataFrame, idx: pd.DatetimeIndex,
                       tickers: List[str], score: Optional[pd.DataFrame], parent_of: Dict[str, str],
                       lam: float, power: float, cap: float, perm: Optional[np.ndarray] = None
                       ) -> Tuple[pd.DataFrame, Dict[str, Any]]:
    """[v0.8.0 R81 ★★] **상승확률 기울임** — 1/N 균등을 버리고 '상승 확률이 높은 종목'에 더 준다(사용자 지시).

    사용자 지시(2026-09-21): "비중 0.035 이런 식으로 다 똑같이 주지 말라니까 — 섹터, 산업, 나머지 지표 참고해서
    가장 상승 확률 높은 거에 비중을 주라고".
    점수 = 그 종목의 산업 ETF **결합점수 백분위**(I build_coupling_state: 산업↔부모 상관 · 1−특이변동성비중 ·
      부모(섹터) 변동성 — 전부 자기이력 백분위, 인과). 섹터·산업·변동성 지표를 합친 값이다.
      R81 실측(리포트 i26·k7): 29개 산업 횡단면 향후 21일 IC **+0.059 · t 2.67 · 8/9년 양수** — 같은 리포트에서
      시험한 후보 20여 개 가운데 유일하게 유의했다(복합점수 −0.018 · 종목 모멘텀 −0.03 · 워크포워드 로지스틱 +0.003).

    단계: (1) 기준 형태 b = elig/N (v0.6.0 1/N 고정슬리브 — 감축·미관측 종목 0)
          (2) 점수 형태 g = score^power (보유 적격 종목만) — power가 클수록 상위 종목에 몰린다
          (3) 형태 = (1−λ)·b/Σb + λ·g/Σg → **1/N 규칙의 그날 총노출로 스케일**(방어 불변)
          (4) 종목 상한 cap(그날 평균비중 밑으로는 내리지 않는다) · 초과분 같은 날 재분배 4회
    점수가 없는 종목(산업 ETF 매핑 실패 · 결합점수 이력 부족)은 **0.5(중립)** — 연동을 끄는 스위치가 아니다
      (v0.7.0의 MIN_COVER 스위치가 65% 날짜에서 기울임 전체를 꺼 1/N만 남긴 결함을 되풀이하지 않는다).
    perm: 무작위 대조군용 — 점수 열을 종목에 무작위로 재배정(분포·집중도는 같고 매핑만 무작위).
    ⚠ 룩어헤드 없음: 점수는 I가 t일까지로 확정한 값(reindex는 ffill만), 체결은 build_allocation이 t+1로 민다."""
    n = max(1, len(tickers))
    elig = solo.fillna(0.0).clip(lower=0.0, upper=1.0).where(live, 0.0)
    base = elig / float(n)
    tot = base.sum(axis=1)
    held = elig > 1e-9
    n_elig = held.sum(axis=1)
    covered = 0
    S = pd.DataFrame(0.5, index=idx, columns=tickers)
    if isinstance(score, pd.DataFrame) and len(score):
        sc = score.reindex(score.index.union(idx)).sort_index().ffill().reindex(idx)
        for t in tickers:
            e = str(parent_of.get(t, "") or "")
            if e and e in sc.columns:
                S[t] = pd.to_numeric(sc[e], errors="coerce").values
                covered += 1
    S = S.clip(0.0, 1.0).fillna(0.5)
    if perm is not None:
        S = pd.DataFrame(S.values[:, np.asarray(perm)], index=idx, columns=tickers)
    g = (S ** float(power)).where(held, 0.0)
    g = g.div(g.sum(axis=1).replace(0.0, np.nan), axis=0).fillna(0.0)
    b = base.div(tot.replace(0.0, np.nan), axis=0).fillna(0.0)
    Sh = (1.0 - float(lam)) * b + float(lam) * g
    W = Sh.mul(tot, axis=0)
    cap_in = float(cap)
    cap_row = pd.Series(cap_in, index=idx).clip(lower=(tot / n_elig.replace(0, np.nan)).fillna(cap_in))
    rounds = 0
    for _ in range(4):
        over = W.sub(cap_row, axis=0).clip(lower=0.0)
        if float(over.values.sum()) < 1e-12:
            break
        rounds += 1
        W = W.clip(upper=cap_row, axis=0)
        room = ((-W).add(cap_row, axis=0)).clip(lower=0.0) * (Sh > 0)
        W = W + room.div(room.sum(axis=1).replace(0.0, np.nan), axis=0).mul(over.sum(axis=1), axis=0).fillna(0.0)
    W = W.clip(lower=0.0).clip(upper=cap_row, axis=0)
    hw = W.where(W > 1e-9)
    diag = {"lam": float(lam), "power": float(power), "cap": cap_in, "covered": int(covered), "n": int(n),
            "cap_lift_days": int((cap_row > cap_in + 1e-12).sum()), "redistribute_rounds": rounds,
            "tot_gap_max": round(float((W.sum(axis=1) - tot).abs().max()), 8),
            "cv_mean": (round(float((hw.std(axis=1) / hw.mean(axis=1)).mean()), 3) if len(hw.dropna(how="all")) else None),
            "top5_share": round(float((W.apply(lambda r_: r_.nlargest(5).sum(), axis=1)
                                       / W.sum(axis=1).replace(0.0, np.nan)).mean()), 4),
            "score_ok": bool(isinstance(score, pd.DataFrame) and len(score) and covered > 0)}
    return W, diag


# =============================================================================
# [4b] ★★ v0.3.0 D2 신규 — 배분층(전체자산 1.0)
#   사용자 지시: "배분전략 거래 할거면 전체자산을 1로 해서 그걸 배분해서 각 총합이 1이되도록 하라고
#                왜 자꾸 각 티커별로 비중이 1이냐고"
#   지적이 정확했다. v0.2.1까지 build_positions는 **티커마다 독립적으로** 0/1을 줬고, 28종목이면
#   목표비중 합계가 실측 평균 **26.46**(최대 28.0)이었다 — 28배 레버리지다. 01Z 시트에 그 값이
#   그대로 찍혀 있었고 사용자가 그것을 봤다.
#   ⇒ 이제 배분층이 **전체자산 1.0을 나눠 담는다.** build_positions는 '그 종목 단독 신호'를 내는
#     진단·채점용으로 남고(00A 시트 ②열·03 시트가 쓴다), 실제 포트는 이 함수가 만든다.
# =============================================================================
def build_allocation(pos: Dict[str, pd.DataFrame], panel: Dict[str, pd.DataFrame],
                     cfg: StockConfig, mode: Optional[str] = None,
                     max_weight: Optional[float] = None, top_k: Optional[int] = None,
                     parent_w: Optional[pd.DataFrame] = None,
                     parent_of: Optional[Dict[str, str]] = None,
                     ind_alloc: Optional[Dict[str, Any]] = None,
                     tilt_lambda: Optional[float] = None, tilt_cap: Optional[float] = None,
                     tilt_source: Optional[str] = None,
                     tilt_perm: Optional[np.ndarray] = None,
                     prob_power: Optional[float] = None) -> Dict[str, Any]:
    """전체자산 **1.0**을 종목에 배분한다. 반환 target_w의 **행 합계는 절대 1.0을 넘지 않는다**.

    체결 규칙은 M·S·I와 같다 — t일 확정, t+1일 집행(exec_w(t) = target_w(t−1)).

    모드(STOCK_ALLOC_MODE):
      **"equal_fixed"(라이브 · 기본)** — 종목마다 **1/N의 고정 슬리브**를 준다(N = 유니버스 종목수).
        그 종목의 단독 신호가 '감축'이면 그 슬리브는 **현금**으로 간다(다른 종목에 안 넘긴다).
        ⇒ 전 종목 보유일 합계 = 1.0(사용자 요구 '비중 최대로'의 상한), 감축일수만큼 합계가 내려간다
          (사용자 요구 '비중 최대로 감축'). **두 요구를 동시에 만족하는 유일한 단순 규칙이다.**
        왜 재배분하지 않는가: 감축분을 남은 종목에 넘기면 합계가 항상 1.0이 되어 **방어가 사라진다**
          (단순한 순환매가 된다). 방어를 원하면 그 슬리브는 현금이어야 한다.
      "equal_eligible" — 보유 적격 종목에 **균등 재배분**(합계 항상 1.0 · 방어 없음 · 대조군).
      "topk_mom"       — mom63 자기이력 분위 상위 top_k에 균등(선택에 값이 있는지 검정).
      "inv_vol"        — 적격 종목을 vol21 역수 가중(위험 균등).
      "parent_linked"  — **I 계층이 그 종목의 부모 산업에 준 비중**을 그대로 쓴다(4계층 정합의 본래 설계).
                         parent_w(날짜×산업ETF)와 parent_of가 있어야 하고, 없으면 equal_fixed로 되돌린다.
      **"prob_tilt"(v0.8.0 R81 라이브 · 기본)** — 사용자 지시 "다 똑같이 주지 말고 가장 상승 확률 높은 거에 비중".
        총노출은 equal_fixed와 날마다 동일(방어 불변). 그 노출을 산업 **결합점수**(섹터·산업·변동성 지표)의
        power 제곱에 비례해 기울인다. 자세한 근거·실측은 _prob_tilt_weights와 CFG 주석 참조.
      "industry_tilt"(v0.7.0 R80 · R81부터 격자 전용) — 사용자 지시 "주식도 산업 비중을 참고해서 배분".
        **총노출은 equal_fixed와 날마다 동일**하게 두고(방어 불변), 그 노출을 산업/섹터 비중을 참고해
        종목 간에 다시 나눈다: 형태 = (1−λ)·1/N + λ·(산업비중 + 그 섹터 부모ETF 잔여다리 균등분배),
        종목 상한 ALLOC_TILT_CAP, 넘친 몫은 같은 날 다른 종목에 재분배. 산업비중 출처가 없으면
        equal_fixed로 되돌리고 그 사실을 00 시트와 로그에 적는다. 자세한 근거는 CFG 주석 참조.

    ⚠ 모든 모드에서 마지막에 **행 합계 > 1.0이면 정규화**한다(안전장치 — 상한을 코드로 보장한다).
    ⚠ 룩어헤드 없음: 쓰는 값은 그날까지의 자기이력 분위와 그날 확정된 단독 신호뿐이다.
       순위·분위는 expanding만 쓴다(정렬은 그날 횡단면이므로 미래를 보지 않는다)."""
    mode = str(mode if mode is not None else getattr(cfg, "STOCK_ALLOC_MODE", "equal_fixed")).lower()
    mw = float(max_weight if max_weight is not None else getattr(cfg, "STOCK_MAX_WEIGHT", 0.10))
    tk = int(top_k if top_k is not None else getattr(cfg, "STOCK_TOP_K", 8))
    tickers = sorted(panel)
    if not tickers:
        return {"target_w": pd.DataFrame(), "mode": mode, "note": "종목 없음"}
    idx = pos[tickers[0]].index
    for t in tickers:
        idx = idx.union(pos[t].index)
    idx = pd.DatetimeIndex(sorted(idx))
    # 단독 신호(그날 보유 적격인가) — build_positions의 목표비중 > 0
    solo = pd.DataFrame({t: pd.to_numeric(pos[t]["목표비중"], errors="coerce").reindex(idx)
                         for t in tickers})
    hold = (solo.fillna(0.0) > 1e-9)
    # 관측 여부(그 종목이 그날 존재했나) — 없는 종목에 슬리브를 주면 현금이 과대평가된다
    live = pd.DataFrame({t: pd.to_numeric(panel[t]["종가"], errors="coerce").reindex(idx).notna()
                         for t in tickers})
    n_uni = max(1, len(tickers))
    W = pd.DataFrame(0.0, index=idx, columns=tickers)

    if mode == "equal_fixed":
        # 고정 슬리브 = 1/N. 관측되지 않는 종목의 슬리브도 현금(그 종목을 살 수 없었다).
        #   부분 감축(CUT_WEIGHT>0)은 그 비율만큼만 담는다 — solo 값을 그대로 곱한다.
        W = solo.fillna(0.0).clip(lower=0.0, upper=1.0) * (1.0 / float(n_uni))
        W = W.where(live, 0.0)
    elif mode == "prob_tilt":
        _ia = ind_alloc if ind_alloc is not None else _resolve_industry_alloc(cfg, parent_w)[0]
        _sc = (_ia or {}).get("coupling_score")
        if not isinstance(_sc, pd.DataFrame) or not len(_sc):
            log("ALLOC", kv(event="prob_tilt_unavailable", fallback="equal_fixed",
                            note="I 결합점수 통로가 없다 — run_pipeline.main()으로 I와 함께 돌릴 것(I v0.35.0+)"),
                level="warning")
            _r = build_allocation(pos, panel, cfg, mode="equal_fixed", max_weight=mw, top_k=tk)
            _r["tilt"] = {"ok": False, "note": "I 결합점수 출처 없음 — 1/N 고정슬리브로 되돌림"}
            return _r
        _lam = float(tilt_lambda if tilt_lambda is not None else getattr(cfg, "PROB_TILT_LAMBDA", 0.5))
        _pw = float(prob_power if prob_power is not None else getattr(cfg, "PROB_TILT_POWER", 4.0))
        _cap = float(tilt_cap if tilt_cap is not None else getattr(cfg, "PROB_TILT_CAP", 0.10))
        W, _tdiag = _prob_tilt_weights(solo, live, idx, tickers, _sc, dict(parent_of or {}),
                                       lam=_lam, power=_pw, cap=_cap, perm=tilt_perm)
        _tdiag["ok"] = True
        _tdiag["source"] = "coupling"
        log("ALLOC", kv(event="prob_tilt_built", lam=_lam, power=_pw, cap=_cap, covered=_tdiag["covered"],
                        n=_tdiag["n"], cv_mean=_tdiag["cv_mean"], top5_share=_tdiag["top5_share"],
                        cap_lift_days=_tdiag["cap_lift_days"], tot_gap_max=_tdiag["tot_gap_max"],
                        control=(tilt_perm is not None),
                        note="★ 총노출은 1/N 규칙과 동일 — 상승확률(결합점수) 높은 종목에 더 준다"))
    elif mode == "industry_tilt":
        _ia = ind_alloc if ind_alloc is not None else _resolve_industry_alloc(cfg, parent_w)[0]
        if not _ia:
            log("ALLOC", kv(event="industry_tilt_unavailable", fallback="equal_fixed",
                            note="I 산업비중 통로가 없다 — run_pipeline.main()으로 I와 함께 돌릴 것"),
                level="warning")
            _r = build_allocation(pos, panel, cfg, mode="equal_fixed", max_weight=mw, top_k=tk)
            _r["tilt"] = {"ok": False, "note": "I 산업비중 출처 없음 — 1/N 고정슬리브로 되돌림"}
            return _r
        _lam = float(tilt_lambda if tilt_lambda is not None else getattr(cfg, "ALLOC_TILT_LAMBDA", 0.25))
        _cap = float(tilt_cap if tilt_cap is not None else getattr(cfg, "ALLOC_TILT_CAP", 0.10))
        _src = str(tilt_source if tilt_source is not None else getattr(cfg, "ALLOC_TILT_SOURCE", "industry"))
        W, _tdiag = _industry_tilt_weights(solo, live, idx, tickers, cfg, _ia, dict(parent_of or {}),
                                           lam=_lam, cap=_cap, source=_src,
                                           min_cover=float(getattr(cfg, "ALLOC_TILT_MIN_COVER", 0.50)),
                                           perm=tilt_perm)
        _tdiag["ok"] = True
        log("ALLOC", kv(event="industry_tilt_built", lam=_lam, cap=_cap, source=_src,
                        thin_days=_tdiag["thin_days"], cover_mean=_tdiag["cover_mean"],
                        redistribute_rounds=_tdiag["redistribute_rounds"],
                        tot_gap_max=_tdiag["tot_gap_max"],
                        note="★ 총노출은 1/N 규칙과 동일 — 바뀐 것은 종목 간 분배뿐이다"))
    elif mode == "equal_eligible":
        elig = (hold & live)
        cnt = elig.sum(axis=1).replace(0, np.nan)
        W = elig.astype(float).div(cnt, axis=0).fillna(0.0)
    elif mode == "topk_mom":
        mom = pd.DataFrame({t: pd.to_numeric(panel[t].get("mom63_pct"), errors="coerce").reindex(idx)
                            for t in tickers})
        mom = mom.where(hold & live)
        rnk = mom.rank(axis=1, ascending=False, method="first")
        sel = (rnk <= float(max(1, tk))) & mom.notna()
        cnt = sel.sum(axis=1).replace(0, np.nan)
        W = sel.astype(float).div(cnt, axis=0).fillna(0.0)
    elif mode == "inv_vol":
        vol = pd.DataFrame({t: pd.to_numeric(panel[t].get("vol21"), errors="coerce").reindex(idx)
                            for t in tickers})
        inv = (1.0 / vol.where(vol > 1e-9)).where(hold & live)
        W = inv.div(inv.sum(axis=1), axis=0).fillna(0.0)
    elif mode == "parent_linked":
        if parent_w is None or parent_of is None or not len(parent_w):
            log("ALLOC", kv(event="parent_linked_unavailable", fallback="equal_fixed",
                            note="I 계층 산업비중(parent_w)이 없다 — run_pipeline이 I를 넘겼는지 확인"),
                level="warning")
            return build_allocation(pos, panel, cfg, mode="equal_fixed",
                                    max_weight=mw, top_k=tk)
        cols = {t: parent_of.get(t, "") for t in tickers}
        W = pd.DataFrame({t: (pd.to_numeric(parent_w[cols[t]], errors="coerce").reindex(idx).fillna(0.0)
                              if cols[t] in parent_w.columns else pd.Series(0.0, index=idx))
                          for t in tickers})
        W = W.where(hold & live, 0.0)
    else:
        log("ALLOC", kv(event="unknown_mode", mode=mode, fallback="equal_fixed"), level="warning")
        return build_allocation(pos, panel, cfg, mode="equal_fixed", max_weight=mw, top_k=tk)

    # ---- 상한·정규화(코드로 보장하는 두 가지 제약) ----
    #   ★★ v0.3.0 D2 버그 수정(테스트가 잡았다): 종목 상한이 **총예산을 깎고 있었다**.
    #     8종목 × 1/8 = 0.125인데 상한 0.10에 걸려 합계 최대가 **0.8**이 됐고, 그래서
    #     equal_fixed와 equal_eligible이 **같은 결과**로 나왔다(둘 다 상한에 눌려서).
    #     상한의 목적은 **집중 억제**(topk·inv_vol 모드)이고 균등 슬리브를 깎는 것이 아니다.
    #   ⇒ 유효 상한 = max(설정 상한, 1/N). 균등 슬리브는 절대 상한에 걸리지 않고,
    #     집중 모드에서는 설정 상한이 그대로 작동한다.
    #   ⚠ 이 완화는 **equal_fixed에만** 적용한다. 슬리브가 정의상 1/N이기 때문이다.
    #     재배분 모드(equal_eligible 등)에까지 올리면 1/N이 상한이 되어 **두 모드가 같아진다**
    #     (테스트가 그 붕괴를 잡았다: 적격 4종목이면 각 0.25를 원하는데 0.125로 잘려 합계 0.5,
    #      즉 고정슬리브와 완전히 동일한 표가 나왔다). 재배분 모드는 설정 상한이 그대로 지배하고,
    #     그래서 적격이 적은 날에는 합계가 1.0에 못 미친다 — 그것은 상한의 **실제 성질**이므로
    #     감추지 않고 로그와 격자의 '비중합 평균'에 그대로 드러낸다.
    #   [v0.7.0 R80] industry_tilt도 같은 완화를 받는다 — 상한은 ALLOC_TILT_CAP이 이미 적용했고,
    #     여기서 STOCK_MAX_WEIGHT로 한 번 더 깎으면 재분배 결과가 무너지면서 총노출이 줄어든다(방어 불변이 깨진다).
    _mw_eff = (max(mw, 1.0 / float(n_uni)) if mode == "equal_fixed"
               else (max(mw, 1.0 / float(n_uni),
                         float(tilt_cap if tilt_cap is not None else getattr(cfg, "ALLOC_TILT_CAP", 0.10)),
                         float(W.max().max()) if len(W) else 0.0)
                     if mode in ("industry_tilt", "prob_tilt") else mw))
    if _mw_eff > mw + 1e-12:
        log("ALLOC", kv(event="cap_lifted_to_equal_sleeve", mode=mode, cap_set=mw,
                        cap_used=round(_mw_eff, 6), n=n_uni,
                        note="고정슬리브는 정의상 1/N이므로 상한을 1/N까지 올린다(재배분 모드는 제외)"))
    W = W.clip(lower=0.0, upper=_mw_eff)                 # 종목 한 칸 상한
    _ssum = W.sum(axis=1)
    _ov = _ssum > 1.0 + 1e-12
    if bool(_ov.any()):
        W.loc[_ov] = W.loc[_ov].div(_ssum[_ov], axis=0)  # ★ 합계 1.0 초과분 정규화
    tot = W.sum(axis=1)
    exec_w = W.shift(1).fillna(0.0)
    ret = pd.DataFrame({t: pd.to_numeric(panel[t]["일간수익"], errors="coerce").reindex(idx)
                        for t in tickers}).fillna(0.0)
    port_ret = (exec_w * ret).sum(axis=1)
    log("ALLOC", kv(event="allocation_built", mode=mode, tickers=len(tickers),
                    max_weight=mw, cap_used=round(_mw_eff, 6),
                    top_k=(tk if mode == "topk_mom" else None),
                    w_sum_mean=round(float(tot.mean()), 4), w_sum_max=round(float(tot.max()), 4),
                    days_sum_over_1=int((tot > 1.0 + 1e-6).sum()),
                    days_sum_ge_09=int((tot >= 0.9).sum()),
                    single_max=round(float(W.max().max()), 4),
                    note="★ 전체자산 1.0 — 행 합계가 1을 넘으면 정규화한다(사용자 지시)"))
    if float(tot.max()) > 1.0 + 1e-6:
        log("ALLOC", kv(event="weight_sum_over_one", w_sum_max=round(float(tot.max()), 4),
                        suggest="정규화가 동작하지 않았다 — clip/정규화 순서를 확인할 것"),
            level="error")
    return {"target_w": W, "exec_w": exec_w, "total_w": tot, "port_ret": port_ret,
            "solo_w": solo.fillna(0.0), "ret": ret, "mode": mode,
            "max_weight": mw, "cap_used": _mw_eff, "top_k": tk,
            "tilt": (_tdiag if mode in ("industry_tilt", "prob_tilt") else None)}


# =============================================================================
# [5] 룩어헤드 감사 — 절단재계산(M·S·I와 같은 방식)
# =============================================================================
def build_lookahead_audit(prices: Dict[str, pd.DataFrame], fund: Dict[str, Dict[str, Any]],
                          cfg: StockConfig) -> pd.DataFrame:
    """[11_룩어헤드감사] 검사일 t까지만 잘라서 다시 계산한 값이 전체 계산과 같은지 확인한다.
    가격 특성과 **펀더멘탈 as-of** 둘 다 검사한다 — 후자가 이 파일에서 가장 위험한 지점이다."""
    rows: List[dict] = []
    tks = list(prices)[: int(cfg.AUDIT_TICKERS)]
    cols = ["ext200_pct", "vol21_pct", "dd63_pct", "mom63_pct"]
    fcols = ["매출_YoY", "EPS_YoY", "영업이익률"]
    for t in tks:
        df = prices[t]
        full = build_price_features(df, cfg)
        ffull, _ = build_fundamental_asof(fund.get(t, {}), df.index, cfg)
        idx = full.index[full.index >= pd.Timestamp(cfg.EVAL_START)]
        if len(idx) < 50:
            continue
        picks = list(pd.Series(idx).iloc[np.linspace(10, len(idx) - 1, num=int(cfg.AUDIT_DATES),
                                                    dtype=int)])
        for d in picks:
            cut = df.loc[:d]
            tr = build_price_features(cut, cfg)
            ftr, _ = build_fundamental_asof(fund.get(t, {}), cut.index, cfg)
            for c in cols:
                a = float(full[c].get(d, np.nan)); b = float(tr[c].get(d, np.nan))
                if pd.isna(a) and pd.isna(b):
                    continue
                rows.append({"티커": t, "검사일": d, "항목": c, "전체계산": a, "절단재계산": b,
                             "차이": (abs(a - b) if pd.notna(a) and pd.notna(b) else np.nan),
                             "일치": ("OK" if (pd.notna(a) and pd.notna(b) and abs(a - b) < 1e-9)
                                    else ("OK(둘 다 NaN)" if pd.isna(a) and pd.isna(b) else "⚠ 불일치")),
                             "감사종류": "가격 특성"})
            for c in fcols:
                if c not in ffull.columns or c not in ftr.columns:
                    continue
                a = float(ffull[c].get(d, np.nan)); b = float(ftr[c].get(d, np.nan))
                if pd.isna(a) and pd.isna(b):
                    rows.append({"티커": t, "검사일": d, "항목": c, "전체계산": np.nan,
                                 "절단재계산": np.nan, "차이": np.nan, "일치": "OK(둘 다 NaN)",
                                 "감사종류": "펀더멘탈 as-of"})
                    continue
                rows.append({"티커": t, "검사일": d, "항목": c, "전체계산": a, "절단재계산": b,
                             "차이": (abs(a - b) if pd.notna(a) and pd.notna(b) else np.nan),
                             "일치": ("OK" if (pd.notna(a) and pd.notna(b) and abs(a - b) < 1e-9)
                                    else "⚠ 불일치"),
                             "감사종류": "펀더멘탈 as-of"})
    out = pd.DataFrame(rows)
    bad = int((out["일치"].astype(str).str.startswith("⚠")).sum()) if len(out) else 0
    log("AUDIT", kv(event="lookahead_audit", checks=len(out), mismatch=bad,
                    note="펀더멘탈 as-of는 발표일(또는 기간말+지연) 기준이라 절단해도 값이 같아야 한다"),
        level=("warning" if bad else "info"))
    return out


# =============================================================================
# [6] 실행 · 리포트
# =============================================================================
# =============================================================================
# [4c] ★★ v0.4.0 R77 — 시장 예산(M E_t) 출처 결정
#   runner는 K.run(K.CFG, k_overrides, parent_w=…)만 부른다(사용자 지시로 runner 무변경). 그래서 K가 스스로 찾는다:
#     (1) run(m_sig=…) 인자  (2) I 모듈 통로 market_budget_handoff() — I.run()이 M res["sig"]를 남긴다(같은 프로세스)
#     (3) MARKET_BUDGET_CSV(M 일별 CSV '목표비중')  (4) 없으면 경고 + 구 규칙(M 예산 없음) — 00시트에 출처를 적는다.
#   값은 **M이 t일 종가로 확정한 목표비중**이다. 체결 지연(t+1)은 build_positions의 집행 규칙이 적용한다.
# =============================================================================
def _resolve_market_budget(cfg: StockConfig, m_sig: Any = None,
                           price_last: Optional[pd.Timestamp] = None) -> Tuple[Optional[pd.Series], Dict[str, Any]]:
    mode = str(getattr(cfg, "MARKET_BUDGET", "none") or "none").lower()
    info: Dict[str, Any] = {"mode": mode, "source": "-", "asof": "-", "rows": 0, "ok": False, "note": ""}
    if mode == "none":
        info.update({"source": "끔(MARKET_BUDGET='none') — v0.3.3 규칙", "note": "구 규칙(base1_cut만)"})
        return None, info
    if mode != "m_inherit":
        info.update({"source": f"알 수 없는 MARKET_BUDGET={mode}", "note": "구 규칙으로 계속"})
        log("RUN", kv(event="market_budget_unknown_mode", mode=mode), level="warning")
        return None, info
    s: Optional[pd.Series] = None
    src = "-"
    try:
        if isinstance(m_sig, pd.DataFrame) and "target_pos" in m_sig.columns:
            s, src = m_sig["target_pos"], "run(m_sig=…) 인자"
        elif isinstance(m_sig, pd.Series):
            s, src = m_sig, "run(m_sig=…) 인자(Series)"
    except Exception:
        s = None
    if s is None:
        for _nm, _mod in list(sys.modules.items()):
            try:
                _fn = getattr(_mod, "market_budget_handoff", None)
            except Exception:
                continue
            if callable(_fn):
                try:
                    _h = _fn()
                except Exception as _e:
                    log("RUN", kv(event="market_handoff_read_failed", module=_nm, err=type(_e).__name__), level="warning")
                    continue
                if isinstance(_h, dict) and isinstance(_h.get("target_pos"), pd.Series) and len(_h["target_pos"]):
                    s, src = _h["target_pos"], f"I 모듈 통로({_nm}.market_budget_handoff · {_h.get('source', '-')})"
                    break
    if s is None:
        _p = str(getattr(cfg, "MARKET_BUDGET_CSV", "") or "")
        if _p and os.path.exists(_p):
            try:
                _d = pd.read_csv(_p, encoding="utf-8-sig")
                _d["날짜"] = pd.to_datetime(_d["날짜"], errors="coerce")
                _d = _d.dropna(subset=["날짜"])
                s = pd.Series(pd.to_numeric(_d["목표비중"], errors="coerce").values, index=pd.DatetimeIndex(_d["날짜"]))
                src = f"M 일별 CSV({_p})"
            except Exception as _e:
                log("RUN", kv(event="market_budget_csv_failed", path=_p, err=type(_e).__name__, msg=str(_e)[:120]),
                    level="warning")
                s = None
    if s is None:
        info.update({"source": "없음 — I 통로·M CSV 모두 없음", "note": "⚠ 구 규칙(base1_cut만)으로 실행 — 시장 하락을 못 피한다"})
        log("RUN", kv(event="market_budget_missing", mode=mode,
                      next_step=("run_pipeline.main()으로 I와 함께 돌리거나 stock_regime.run(m_sig=M결과['sig'])로 넘길 것 — "
                                 "그 전까지 K 라이브는 M 예산 없이(v0.3.3) 돈다")), level="warning")
        return None, info
    s = pd.to_numeric(pd.Series(s), errors="coerce")
    s.index = pd.DatetimeIndex(s.index)
    s = s[~s.index.duplicated(keep="last")].sort_index().dropna().clip(0.0, 1.0)
    info.update({"source": src, "rows": int(len(s)), "asof": (str(s.index[-1].date()) if len(s) else "-"),
                 "mean": (round(float(s.mean()), 4) if len(s) else None)})
    if not len(s):
        info["note"] = "⚠ E_t 값이 비어 있다 — 구 규칙"
        return None, info
    _stale = int(getattr(cfg, "MARKET_BUDGET_MAX_STALE_DAYS", 5))
    if price_last is not None and (pd.Timestamp(price_last) - s.index[-1]).days > _stale:
        info.update({"note": f"⚠ E_t 마지막일 {s.index[-1].date()}가 가격 마지막일 {pd.Timestamp(price_last).date()}보다 "
                             f"{(pd.Timestamp(price_last) - s.index[-1]).days}일 뒤처져 쓰지 않는다 — 구 규칙"})
        log("RUN", kv(event="market_budget_stale", source=src, asof=str(s.index[-1].date()),
                      price_last=str(pd.Timestamp(price_last).date()), max_stale_days=_stale), level="warning")
        return None, info
    info.update({"ok": True, "note": "적용 — 목표비중 = min(base1_cut, E_t)"})
    log("RUN", kv(event="market_budget_resolved", source=src[:80], rows=len(s), asof=info["asof"],
                  mean_e=info["mean"], zero_share=round(float((s <= 1e-9).mean()), 4),
                  partial_share=round(float(((s > 1e-9) & (s < 1 - 1e-9)).mean()), 4)))
    return s, info


def _updown_variants(panel: Dict[str, pd.DataFrame], pos: Dict[str, pd.DataFrame], cfg: StockConfig,
                     mkt: Optional[pd.Series]) -> Dict[str, Any]:
    """[v0.4.0 R77] 00D용 변형(체결 비중 = 목표 shift(1)) — 라이브·구 라이브·후보·반증·참고. build_positions를 그대로 다시 부른다
    (산식 단일 출처). 부분 노출일 추세컷은 K의 ext200 대신 **UPDOWN_COMPARE_SMA일 SMA**를 종가로 새로 계산(I 라이브와 같은 정의)."""
    tick = sorted(panel)
    ex = lambda d: pd.DataFrame(d)
    ref = f"★ 라이브({VERSION} · base1_cut × M E_t)" if mkt is not None else f"★ 라이브({VERSION} · base1_cut — M 예산 없음)"
    V: Dict[str, pd.DataFrame] = {ref: ex({t: pd.to_numeric(pos[t]["집행비중"], errors="coerce") for t in tick})}
    desc = {ref: ("단일 종목 라이브: 기본 1.0 · E3(음의 서프라이즈 후 21일) 0 · 시장 예산 E_t 상한" if mkt is not None
                  else "단일 종목 라이브(시장 예산 출처 없음 — 구 규칙과 같다)")}
    cands: List[str] = []
    fals: List[str] = []
    old = None
    if mkt is not None:
        old = "구 라이브(v0.3.3 · base1_cut · M 예산 없음)"
        V[old] = ex({t: build_positions(panel[t], cfg, ticker=t)["집행비중"] for t in tick})
        desc[old] = "기본 1.0 · E3만 0 — 평균 노출 ≈0.95(사실상 B&H)"
        lbl = "후보: M E_t만(E3 컷 없음)"
        V[lbl] = ex({t: build_positions(panel[t], cfg, rule="m_only", ticker=t, market_w=mkt)["집행비중"] for t in tick})
        desc[lbl] = "E3 컷의 값 — 이 행이 ★보다 나으면 E3가 손해"
        cands.append(lbl)
        n = int(getattr(cfg, "UPDOWN_COMPARE_SMA", 200))
        tc, zr, fl = {}, {}, {}
        for t in tick:
            tp = pd.to_numeric(pos[t]["목표비중"], errors="coerce")
            px = pd.to_numeric(panel[t]["종가"], errors="coerce")
            sma = px.rolling(n, min_periods=n).mean()
            _E = pd.to_numeric(pos[t].get("시장예산(M E_t)", pd.Series(np.nan, index=tp.index)), errors="coerce")
            mid = (_E > 1e-9) & (_E < 1.0 - 1e-9)
            ok = px.notna() & sma.notna()
            tc[t] = tp.where(~(mid & ok & (px < sma)), 0.0).shift(1).fillna(0.0)
            zr[t] = tp.where(~mid, 0.0).shift(1).fillna(0.0)
            fl[t] = tp.where(~(mid & ok & (px >= sma)), 0.0).shift(1).fillna(0.0)
        for lbl, d, ds, bucket in ((f"후보: + 부분 노출일 추세컷 SMA{n}", tc, f"0<E_t<1 날 종가 < SMA{n}이면 0(I 라이브 규칙)", cands),
                                   ("후보: + 부분 노출일 전부 0", zr, "0<E_t<1 날 전부 0 — M이 확신한 날만", cands),
                                   (f"반증: 부분 노출일 추세 '위'에서 컷(SMA{n})", fl, "추세컷의 방향을 뒤집은 것 — 열위여야 정상", fals)):
            V[lbl] = ex(d); desc[lbl] = ds; bucket.append(lbl)
    lbl = "참고: 200일선(v0.1.0 라이브)"
    V[lbl] = ex({t: build_positions(panel[t], cfg, rule="ext200", ticker=t)["집행비중"] for t in tick})
    desc[lbl] = "종가 > 200일선이면 1 — v0.1.0에서 양쪽 다 늦다고 판정"
    return {"variants": V, "ref": ref, "old": old, "cands": tuple(cands), "fals": tuple(fals), "desc": desc,
            "market_exec": (mkt.shift(1) if mkt is not None else None)}


def run(cfg: Optional[StockConfig] = None, s_overrides: Optional[Dict[str, Any]] = None,
        parent_w: Optional[pd.DataFrame] = None, m_sig: Any = None) -> Dict[str, Any]:
    """[K 계층 본체] 데이터 → 특성 → 규칙 채점 → **배분(총합 1.0)** → 감사 → 리포트 dict.

    parent_w: [v0.3.0 D2] I 계층이 낸 **산업 ETF 비중**(날짜 × 산업ETF). run_pipeline이 넘겨 주면
      배분격자의 'I계층 산업비중 연동' 행이 살아난다(4계층 정합의 본래 설계). None이면 그 행만 빠진다."""
    cfg = cfg or CFG
    if s_overrides:
        cfg = dataclasses.replace(cfg, **s_overrides)
        log("RUN", kv(event="overrides", detail=json.dumps(s_overrides, ensure_ascii=False)[:300]))
    # [v0.6.0 R79 ★★] 임의 티커 — 역할(설계·사용자·홀드아웃) · 정규화 · 자동 매핑
    U = resolve_universe(cfg)
    tickers = list(U["main"])
    holdout = list(U["holdout"])
    roles = dict(U["role"])
    log("RUN", kv(event="start", version=VERSION, tickers=len(tickers), holdout=len(holdout),
                  eval_start=cfg.EVAL_START, live_rule=cfg.LIVE_RULE,
                  fund_lag_days=cfg.FUND_PUBLISH_LAG_DAYS))
    _FAILED_PX.clear()
    prices_all = download_prices(tickers + holdout, cfg)
    prices = {t: prices_all[t] for t in tickers if t in prices_all}
    prices_h = {t: prices_all[t] for t in holdout if t in prices_all}
    if not prices:
        log("RUN", kv(event="aborted", reason="가격 데이터 0건", failed=";".join(f"{k}={v}" for k, v in _FAILED_PX.items())[:300]),
            level="error")
        return {"aborted": True, "note": "가격 데이터를 하나도 받지 못했다 — " + "; ".join(f"{k}: {v}" for k, v in list(_FAILED_PX.items())[:10]),
                "cfg": cfg}
    fund = download_fundamentals(list(prices) + list(prices_h), cfg)
    # 산업 ETF 매핑(사전등록 → Yahoo 업종·섹터 → 상관 폴백) — 표시·배분격자(I 산업비중 연동)에만 쓴다
    try:
        amap = auto_map_industry(tickers + holdout, U["registered"], cfg, prices=prices_all)
        if bool(getattr(cfg, "AUTO_MAP", True)) and any(r["etf"] is None and t in prices_all for t, r in amap.items()):
            _etf_px = download_prices(sorted(set(STOCK_UNIVERSE) | set(SECTOR_ETFS)), cfg)
            amap = auto_map_industry(tickers + holdout, U["registered"], cfg, prices=prices_all, etf_prices=_etf_px)
    except Exception as e:
        log("MAP", kv(event="auto_map_failed", err=type(e).__name__, msg=str(e)[:160], action="사전등록만 쓰고 계속"),
            level="warning")
        amap = {t: {"etf": U["registered"].get(t), "method": ("사전등록" if t in U["registered"] else "미분류(매핑 실패)"),
                    "sector": None, "industry": None, "name": STOCK_NAME_KR.get(t, t), "corr": None} for t in tickers + holdout}
    _nm = {t: (STOCK_NAME_KR.get(t) or (amap.get(t) or {}).get("name") or t) for t in tickers + holdout}
    # [v0.4.0 R77 ★★] 시장 예산(M E_t) — 출처를 먼저 정한다(없으면 경고 + 구 규칙 · 00시트에 표시)
    try:
        _plast = max(pd.Timestamp(v.index[-1]) for v in prices.values() if v is not None and len(v))
    except Exception:
        _plast = None
    mkt, mkt_info = _resolve_market_budget(cfg, m_sig=m_sig, price_last=_plast)

    panel: Dict[str, pd.DataFrame] = {}
    pos: Dict[str, pd.DataFrame] = {}
    fund_ledgers: List[pd.DataFrame] = []
    earn_ledgers: List[pd.DataFrame] = []
    quality: List[dict] = []
    parent_of = {t: ((amap.get(t) or {}).get("etf") or "") for t in tickers + holdout}
    panel_h: Dict[str, pd.DataFrame] = {}      # [v0.6.0 R79] 홀드아웃(검증 전용 — 배분·06 포트·00D 제외)
    pos_h: Dict[str, pd.DataFrame] = {}

    def _one_ticker(t: str, df: pd.DataFrame, role_: str) -> Optional[Tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame, pd.DataFrame]]:
        """한 종목: 특성(가격·펀더멘탈·어닝) → 평가창 → 라이브 비중. 티커와 무관한 같은 산식(설계·사용자·홀드아웃 공통)."""
        pf = build_price_features(df, cfg)
        ff, fl = build_fundamental_asof(fund.get(t, {}), df.index, cfg)
        ef, el = build_earnings_features(fund.get(t, {}), df.index, pf["종가"], cfg)
        gf = build_earnings_fundamentals(fund.get(t, {}), df.index, cfg)   # [v0.2.0 K1]
        feat = pd.concat([pf, ff, ef, gf], axis=1)
        feat = feat.loc[feat.index >= pd.Timestamp(cfg.EVAL_START)]
        _base = {"티커": t, "역할": role_, "산업ETF": parent_of.get(t, ""), "매핑 방법": (amap.get(t) or {}).get("method", "-"),
                 "이름": _nm.get(t, "")}
        if len(feat) < 250:
            # [v0.2.0 K6] 제외 사유를 02 시트에 **같은 열 구성으로** 남긴다 — v0.1.0은 열이 달라
            #   AVB가 표에서 통째로 사라졌고, 왜 빠졌는지 리포트만 보고는 알 수 없었다.
            quality.append({**_base, "관측일(평가창)": len(feat), "상태": f"⚠ 제외 — 평가창 관측 {len(feat)} < 250(상장 1년 미만 등)",
                            "시작": (str(feat.index[0].date()) if len(feat) else "-"),
                            "종료": (str(feat.index[-1].date()) if len(feat) else "-")})
            log("FEAT", kv(event="ticker_excluded", ticker=t, role=role_, obs=len(feat),
                           reason="평가창 관측 250일 미만"), level="warning")
            return None
        ps = build_positions(feat, cfg, ticker=t, market_w=mkt)
        _has_e = bool(pd.to_numeric(feat.get("어닝_서프라이즈%"), errors="coerce").notna().any()) if "어닝_서프라이즈%" in feat.columns else False
        quality.append({**_base, "관측일(평가창)": len(feat),
                        "시작": str(feat.index[0].date()), "종료": str(feat.index[-1].date()),
                        "펀더멘탈 분기수": (int(pd.to_numeric(feat.get("펀더멘탈_분기수"),
                                                        errors="coerce").max())
                                    if "펀더멘탈_분기수" in feat.columns
                                    and pd.to_numeric(feat["펀더멘탈_분기수"],
                                                      errors="coerce").notna().any() else 0),
                        "유효일 출처": (";".join(sorted(set(fl["유효일 출처"].astype(str)))) if len(fl) else "-"),
                        "선택 항목": (str(fl["선택 항목"].iloc[0]) if (len(fl) and "선택 항목" in fl.columns)
                                  else "-"),
                        "어닝 이벤트수": (int(len(el)) if len(el) else 0),
                        # [v0.2.0 K1] 어닝 기반 EPS YoY가 실제로 몇 %의 날에 있는가 —
                        #   v0.1.0에서 재무제표 기반 F 계열이 측정 불가였던 것을 여기서 바로 확인한다.
                        "EPS YoY(어닝) 유효비율": (round(float(pd.to_numeric(feat.get("EPS_YoY_E"),
                                                                     errors="coerce").notna().mean()), 4)
                                            if "EPS_YoY_E" in feat.columns else 0.0),
                        "매출 YoY(재무제표) 유효비율": (round(float(pd.to_numeric(feat.get("매출_YoY"),
                                                                        errors="coerce").notna().mean()), 4)
                                               if "매출_YoY" in feat.columns else 0.0),
                        "상태": ("정상" if _has_e else "정상(⚠ 어닝 자료 없음 — E3 컷 없이 M E_t만)"),
                        "결측 비율(ext200)": round(float(feat["ext200"].isna().mean()), 4)})
        return feat, ps, fl, el

    for t in tickers:
        df = prices.get(t)
        if df is None:
            continue
        o = _one_ticker(t, df, roles.get(t, "설계"))
        if o is None:
            continue
        feat, ps, fl, el = o
        panel[t] = feat
        pos[t] = ps
        if len(fl):
            fl2 = fl.copy(); fl2.insert(0, "티커", t); fund_ledgers.append(fl2.reset_index(drop=True))
        if len(el):
            el2 = el.copy(); el2.insert(0, "티커", t); earn_ledgers.append(el2)
    for t in holdout:
        df = prices_h.get(t)
        if df is None:
            continue
        o = _one_ticker(t, df, "홀드아웃")
        if o is not None:
            panel_h[t], pos_h[t] = o[0], o[1]
    # [v0.2.0 K6] 다운로드 자체가 실패한 티커도 02 시트에 남긴다 — prices에 없으면 위 루프를
    #   아예 통과하지 못해 v0.1.0에서는 '29개 요청 → 28행'의 차이를 리포트로 설명할 수 없었다.
    for t in tickers + holdout:
        if t not in prices_all:
            _why = _FAILED_PX.get(t, "로그 DATA 단계 참조")
            quality.append({"티커": t, "역할": roles.get(t, "-"), "산업ETF": parent_of.get(t, ""),
                            "매핑 방법": (amap.get(t) or {}).get("method", "-"),
                            "이름": _nm.get(t, ""), "관측일(평가창)": 0,
                            "상태": f"⚠ 제외 — 가격 다운로드 실패: {_why}",
                            "시작": "-", "종료": "-"})
            log("FEAT", kv(event="ticker_excluded", ticker=t, role=roles.get(t, "-"), obs=0,
                           reason=f"가격 다운로드 실패({_why})"), level="warning")
    for _raw, _why in U.get("dropped") or []:
        quality.append({"티커": _raw, "역할": "입력 제외", "상태": f"⚠ 입력 제외 — {_why}", "관측일(평가창)": 0})
    if not panel:
        return {"aborted": True, "note": "평가창 관측이 충분한 티커가 없다", "cfg": cfg,
                "quality": pd.DataFrame(quality)}
    log("FEAT", kv(event="features_built", tickers=len(panel),
                    with_fundamentals=int(sum(1 for t in panel
                                              if pd.to_numeric(panel[t].get("매출_YoY"),
                                                               errors="coerce").notna().any())),
                    with_earnings=int(sum(1 for t in panel
                                          if pd.to_numeric(panel[t].get("어닝_서프라이즈%"),
                                                           errors="coerce").notna().any()))))
    acc = build_rule_accuracy(panel, cfg)
    audit = build_lookahead_audit(prices, fund, cfg)

    # ---- 성과 요약 + [v0.2.0 K4 노출격자] ----
    #   ★ 달력 대조군이 함께 실린다 — "신호가 좋은 날을 골랐나"와 "그냥 노출을 줄여 MDD가 좋아졌나"를
    #     가르는 유일한 방법이다(I 계층에서 이 대조군이 세 번 설계를 살렸다).
    perf: List[dict] = []
    _live_lbl = f"★ 라이브({cfg.LIVE_RULE}{' × M E_t' if mkt is not None else ''})"    # [v0.4.0 R77]
    _grid = tuple(getattr(cfg, "EXPOSURE_GRID", ()) or ())
    # (K6 ★) 라벨별로 (티커, 일간수익, 집행비중)을 모아 **동일가중 포트폴리오** 행을 만든다.
    #   왜: 사용자 질문("B&H 대비 하락을 피했고 상승을 탔나")의 단위는 종목이 아니라 계층이다.
    #   종목별 중위 칼마는 각 종목의 좋은 해가 서로 다른 해라서 포트 칼마와 전혀 다른 값이 된다.
    _agg: Dict[str, List[Tuple[str, pd.Series, pd.Series]]] = {}
    for t, p in pos.items():
        r = pd.to_numeric(p["전략일간수익"], errors="coerce").fillna(0.0)
        b = pd.to_numeric(panel[t]["일간수익"], errors="coerce").fillna(0.0)
        _lw = pd.to_numeric(p["집행비중"], errors="coerce")
        # ★ (lbl, 일간수익, **그 행의 집행비중**) — v0.2.0 이전에는 모든 격자 행이 라이브 노출을
        #   찍어서 "평균노출" 열이 전부 같은 값이었다. 격자의 핵심 지표가 노출이므로 치명적이었다.
        _rows: List[Tuple[str, pd.Series, pd.Series]] = [
            (_live_lbl, r, _lw),
            ("매수보유", b, pd.Series(1.0, index=b.index))]
        for _g in _grid:
            # (라벨, 규칙, 감축비중[, CUT_RULES, CUT_MIN_AGREE]) — 뒤 2개는 생략 가능
            _lbl, _rule, _cw = _g[0], _g[1], _g[2]
            _cr = _g[3] if len(_g) > 3 else None
            _ma = _g[4] if len(_g) > 4 else None
            _mk = (mkt if (len(_g) > 5 and bool(_g[5])) else None)     # [v0.4.0 R77] 6번째 = 시장 예산 적용
            if len(_g) > 5 and bool(_g[5]) and mkt is None:
                continue                                             # 출처가 없으면 그 행은 구 규칙과 같다 — 싣지 않는다
            try:
                _pp = build_positions(panel[t], cfg, rule=_rule, cut_weight=_cw,
                                      cut_rules=_cr, cut_min_agree=_ma, ticker=t, market_w=_mk)
                _rows.append((f"[노출격자] {_lbl}",
                              pd.to_numeric(_pp["전략일간수익"], errors="coerce").fillna(0.0),
                              pd.to_numeric(_pp["집행비중"], errors="coerce")))
                if str(_rule).lower() == "base1_cut":
                    _pc = build_positions(panel[t], cfg, rule=_rule, cut_weight=_cw,
                                          cut_rules=_cr, cut_min_agree=_ma,
                                          calendar_control=True, ticker=t, market_w=_mk)
                    _rows.append((f"[노출격자·대조] {_lbl} 같은날수 달력(신호없음)",
                                  pd.to_numeric(_pc["전략일간수익"], errors="coerce").fillna(0.0),
                                  pd.to_numeric(_pc["집행비중"], errors="coerce")))
            except Exception as e:
                log("PERF", kv(event="exposure_grid_row_failed", ticker=t, row=str(_lbl),
                               err=str(e)[:100]), level="warning")
        for lbl, s, _w in _rows:
            _agg.setdefault(lbl, []).append((t, s, _w))
            cur = (1.0 + s).cumprod()
            yrs = max(len(s) / 252.0, 1e-9)
            cagr = float(cur.iloc[-1]) ** (1.0 / yrs) - 1.0
            mdd = float((cur / cur.cummax() - 1.0).min())
            perf.append({"티커": t, "이름": _nm.get(t, ""),
                         "산업ETF": parent_of.get(t, ""), "전략": lbl,
                         "총수익배수": round(float(cur.iloc[-1]), 4), "CAGR": round(cagr, 4),
                         "최대낙폭(MDD)": round(mdd, 4),
                         "칼마(CAGR/MDD)": (round(cagr / abs(mdd), 3) if mdd < -1e-9 else None),
                         "연변동성": round(float(s.std() * math.sqrt(252.0)), 4),
                         "샤프": (round(float(s.mean() / s.std() * math.sqrt(252.0)), 3)
                                if float(s.std()) > 0 else None),
                         "일간승률": round(float((s > 0).mean()), 4),
                         "평균노출": round(float(_w.mean()), 4)})
    # ---- [v0.3.0 D2 ★★] 배분층 — 전체자산 1.0 ----
    #   사용자 지적("왜 자꾸 각 티커별로 비중이 1이냐")의 직접 해결. build_positions는 단독 신호를
    #   계속 내지만(00A ②열·03 채점이 쓴다) **포트는 이제 이 배분층이 만든다**.
    #   [v0.7.0 R80] 산업/섹터 비중 출처는 **한 번만** 찾아 격자 전체가 같은 자료를 쓴다(sys.modules 반복 스캔 방지).
    ind_alloc, ind_info = _resolve_industry_alloc(cfg, parent_w)
    alloc = build_allocation(pos, panel, cfg, parent_w=parent_w, parent_of=parent_of, ind_alloc=ind_alloc)
    alloc_rows: List[dict] = []

    def _alloc_row(lbl: str, a: Dict[str, Any], mw_: float, tk_: Optional[int]) -> Optional[dict]:
        """배분격자 한 행 — 모든 행이 **같은 잣대**를 쓰도록 지표 계산을 한 곳에 둔다(v0.7.0에서 분리)."""
        pr = a.get("port_ret")
        if pr is None or not len(pr):
            return None
        cur = (1.0 + pr.fillna(0.0)).cumprod()
        yrs = max(len(pr) / 252.0, 1e-9)
        cg = float(cur.iloc[-1]) ** (1.0 / yrs) - 1.0
        mdd = float((cur / cur.cummax() - 1.0).min())
        tw = a["total_w"]
        sd = float(pr.std())
        return {"배분방식": lbl, "mode": a["mode"], "종목상한": mw_, "top_k": (tk_ or None),
                "총수익배수": round(float(cur.iloc[-1]), 4),
                "단순합(%)": round(float(pr.sum()) * 100.0, 2),
                "CAGR": round(cg, 4), "최대낙폭(MDD)": round(mdd, 4),
                "칼마(CAGR/MDD)": (round(cg / abs(mdd), 3) if mdd < -1e-9 else None),
                "연변동성": round(sd * math.sqrt(252.0), 4),
                "샤프": (round(float(pr.mean()) / sd * math.sqrt(252.0), 3) if sd > 0 else None),
                "비중합 평균": round(float(tw.mean()), 4),
                "비중합 최대": round(float(tw.max()), 4),
                "비중합 0.9이상 일수": int((tw >= 0.9).sum()),
                "★ 1.0 초과일": int((tw > 1.0 + 1e-6).sum()),
                "종목 최대비중": round(float(a["target_w"].max().max()), 4),
                "평균 보유종목": round(float((a["target_w"] > 1e-9).sum(axis=1).mean()), 1)}

    for _g in tuple(getattr(cfg, "ALLOC_GRID", ()) or ()):
        _lbl, _md, _mw, _tk = _g[0], _g[1], _g[2], _g[3]
        try:
            _a = build_allocation(pos, panel, cfg, mode=_md, max_weight=_mw,
                                  top_k=(_tk or None), parent_w=parent_w, parent_of=parent_of,
                                  ind_alloc=ind_alloc)
            _row = _alloc_row(_lbl, _a, _mw, _tk)
            if _row:
                alloc_rows.append(_row)
        except Exception as e:
            log("ALLOC", kv(event="alloc_grid_row_failed", row=str(_lbl), err=str(e)[:120]),
                level="warning")
    # ---- [v0.7.0 R80 · v0.8.0 R81 ★★] 기울임 격자 + 무작위 대조군 ----
    #   사용자 지시를 **그대로 구현한 뒤 그 값을 엔진이 판정하게** 한다.
    #   대조군: 점수(또는 산업비중) 열을 종목에 무작위로 배정한다. 집중도(형태의 분산)는 그대로이고 **매핑만**
    #   무작위이므로, 라이브가 대조군 분포 안에 묻히면 '그 점수에 정보가 있다'는 주장은 이 표본에서 성립하지 않는다.
    #   [v0.8.0] 대조군은 **라이브 모드를 따라간다**(prob_tilt면 결합점수를 섞고, industry_tilt면 산업비중을 섞는다).
    #   ⚠ 지역변수 이름 주의: 이 함수에는 이미 _nm(종목 이름 사전)·_c·_r·_v가 있다 — R80 첫 구현에서 루프 변수
    #     _nm이 그것을 덮어써 리포트가 죽었다(E2E 시험이 잡았다). 이 블록의 임시 이름에는 전부 _tc 접두사를 붙인다.
    _ctrl_rows: List[dict] = []
    _live_mode = str(getattr(cfg, "STOCK_ALLOC_MODE", "equal_fixed")).lower()
    _live_alloc_label: Optional[str] = None
    if ind_alloc:
        _has_cs = isinstance(ind_alloc.get("coupling_score"), pd.DataFrame) and len(ind_alloc.get("coupling_score"))
        if _has_cs:
            for _t in tuple(getattr(cfg, "PROB_TILT_GRID", ()) or ()):
                _lbl, _lam, _pw, _cap = _t[0], float(_t[1]), float(_t[2]), float(_t[3])
                try:
                    _tc_a = build_allocation(pos, panel, cfg, mode="prob_tilt", parent_w=parent_w,
                                              parent_of=parent_of, ind_alloc=ind_alloc,
                                              tilt_lambda=_lam, tilt_cap=_cap, prob_power=_pw)
                    _tc_r = _alloc_row(_lbl, _tc_a, _cap, None)
                    if _tc_r:
                        _tc_r.update({"λ(연동비중)": _lam, "점수제곱": _pw, "연동출처": "산업 결합점수(상승확률)",
                                      "상위5종목 몫": ((_tc_a.get("tilt") or {}).get("top5_share"))})
                        alloc_rows.append(_tc_r)
                        if str(_lbl).startswith("★") and _live_mode == "prob_tilt":
                            _live_alloc_label = str(_lbl)
                except Exception as e:
                    log("ALLOC", kv(event="alloc_prob_row_failed", row=str(_lbl), err=str(e)[:120]), level="warning")
        for _t in tuple(getattr(cfg, "ALLOC_TILT_GRID", ()) or ()):
            _lbl, _lam, _cap, _src = _t[0], float(_t[1]), float(_t[2]), str(_t[3])
            try:
                _tc_a = build_allocation(pos, panel, cfg, mode="industry_tilt", parent_w=parent_w,
                                          parent_of=parent_of, ind_alloc=ind_alloc,
                                          tilt_lambda=_lam, tilt_cap=_cap, tilt_source=_src)
                _tc_r = _alloc_row(_lbl, _tc_a, _cap, None)
                if _tc_r:
                    _tc_r.update({"λ(연동비중)": _lam, "연동출처": ("산업비중+부모잔여" if _src == "industry" else "섹터비중")})
                    alloc_rows.append(_tc_r)
                    if str(_lbl).startswith("★") and _live_mode == "industry_tilt":
                        _live_alloc_label = str(_lbl)
            except Exception as e:
                log("ALLOC", kv(event="alloc_tilt_row_failed", row=str(_lbl), err=str(e)[:120]), level="warning")
        _nc = int(getattr(cfg, "ALLOC_TILT_CONTROLS", 0) or 0)
        _ctl_mode = _live_mode if _live_mode in ("prob_tilt", "industry_tilt") else None
        if _ctl_mode == "prob_tilt" and not _has_cs:
            _ctl_mode = None
        if _nc > 0 and _ctl_mode:
            _rng = np.random.default_rng(int(getattr(cfg, "ALLOC_TILT_SEED", 20260921)))
            if _ctl_mode == "prob_tilt":
                _lam0 = float(getattr(cfg, "PROB_TILT_LAMBDA", 0.5))
                _cap0 = float(getattr(cfg, "PROB_TILT_CAP", 0.10))
                _pw0 = float(getattr(cfg, "PROB_TILT_POWER", 4.0))
                _ctl_desc = f"결합점수를 종목에 무작위 배정(λ{_lam0}·제곱{_pw0:g}·상한{_cap0:.0%})"
            else:
                _lam0 = float(getattr(cfg, "ALLOC_TILT_LAMBDA", 0.25))
                _cap0 = float(getattr(cfg, "ALLOC_TILT_CAP", 0.10))
                _pw0 = None
                _ctl_desc = f"산업비중을 종목에 무작위 배정(λ{_lam0}·상한{_cap0:.0%})"
            _src0 = str(getattr(cfg, "ALLOC_TILT_SOURCE", "industry"))
            for _k in range(_nc):
                try:
                    _tc_a2 = build_allocation(pos, panel, cfg, mode=_ctl_mode, parent_w=parent_w,
                                              parent_of=parent_of, ind_alloc=ind_alloc,
                                              tilt_lambda=_lam0, tilt_cap=_cap0, tilt_source=_src0,
                                              prob_power=_pw0,
                                              tilt_perm=_rng.permutation(len(sorted(panel))))
                    _tc_r2 = _alloc_row(f"대조군{_k}", _tc_a2, _cap0, None)
                    if _tc_r2:
                        _ctrl_rows.append(_tc_r2)
                except Exception as e:
                    log("ALLOC", kv(event="alloc_tilt_control_failed", k=_k, err=str(e)[:120]), level="warning")
            if _ctrl_rows:
                _cdf = pd.DataFrame(_ctrl_rows)
                for _tc_q, _tc_nm in ((0.50, "중앙값"), (0.95, "상위5%")):
                    _tc_row = {"배분방식": f"[무작위 대조군 {_nc}회 · {_tc_nm}] {_ctl_desc}",
                               "mode": "tilt_control", "종목상한": _cap0, "top_k": None, "λ(연동비중)": _lam0,
                               "연동출처": "무작위(대조군)"}
                    for _tc_col in ("총수익배수", "단순합(%)", "CAGR", "최대낙폭(MDD)", "칼마(CAGR/MDD)", "연변동성",
                                    "샤프", "비중합 평균", "비중합 최대", "종목 최대비중", "평균 보유종목"):
                        _tc_v = pd.to_numeric(_cdf.get(_tc_col), errors="coerce").dropna()
                        _tc_row[_tc_col] = (round(float(_tc_v.quantile(1.0 - _tc_q if _tc_col == "최대낙폭(MDD)" else _tc_q)), 4)
                                            if len(_tc_v) else None)
                    alloc_rows.append(_tc_row)
                _live_cal = next((r.get("칼마(CAGR/MDD)") for r in alloc_rows
                                  if _live_alloc_label and str(r.get("배분방식", "")) == _live_alloc_label), None)
                _cq = pd.to_numeric(_cdf["칼마(CAGR/MDD)"], errors="coerce").dropna()
                log("ALLOC", kv(event="tilt_control_summary", mode=_ctl_mode, n=_nc,
                                seed=int(getattr(cfg, "ALLOC_TILT_SEED", 0)), live_calmar=_live_cal,
                                ctrl_median=(round(float(_cq.median()), 3) if len(_cq) else None),
                                ctrl_p95=(round(float(_cq.quantile(0.95)), 3) if len(_cq) else None),
                                pct_rank=((round(float((_cq < float(_live_cal)).mean()) * 100.0, 1)
                                           if (_live_cal is not None and len(_cq)) else None)),
                                note="라이브가 대조군 상위5%보다 낮으면 '그 점수에 정보가 있다'는 주장은 이 표본에서 미성립"))
    # 동일가중 B&H 기준선 한 줄(비교 기준 — 배분격자와 같은 잣대)
    try:
        _eq = alloc["ret"].mean(axis=1)
        _c = (1.0 + _eq.fillna(0.0)).cumprod()
        _y = max(len(_eq) / 252.0, 1e-9)
        _cg = float(_c.iloc[-1]) ** (1.0 / _y) - 1.0
        _mdv = float((_c / _c.cummax() - 1.0).min())
        alloc_rows.insert(0, {"배분방식": f"★ 기준선: {len(panel)}종목 동일가중 B&H(총 1.0)",
                              "mode": "bh_equal", "종목상한": round(1.0 / max(1, len(panel)), 4),
                              "top_k": None, "총수익배수": round(float(_c.iloc[-1]), 4),
                              "단순합(%)": round(float(_eq.sum()) * 100.0, 2),
                              "CAGR": round(_cg, 4), "최대낙폭(MDD)": round(_mdv, 4),
                              "칼마(CAGR/MDD)": (round(_cg / abs(_mdv), 3) if _mdv < -1e-9 else None),
                              "연변동성": round(float(_eq.std() * math.sqrt(252.0)), 4),
                              "비중합 평균": 1.0, "비중합 최대": 1.0,
                              "비중합 0.9이상 일수": int(len(_eq)), "★ 1.0 초과일": 0,
                              "종목 최대비중": round(1.0 / max(1, len(panel)), 4)})
    except Exception as e:
        log("ALLOC", kv(event="alloc_baseline_failed", err=str(e)[:120]), level="warning")

    # ---- (K6 ★ 신규) 동일가중 포트폴리오 행 — 06 시트 맨 앞에 붙는다 ----
    _port: List[dict] = []
    for lbl, items in _agg.items():
        if not items:
            continue
        _R = pd.concat([sr.rename(tk) for tk, sr, _ in items], axis=1).sort_index()
        _W = pd.concat([wr.rename(tk) for tk, _, wr in items], axis=1).sort_index()
        _n = max(1, _R.shape[1])
        s = _R.fillna(0.0).mean(axis=1)          # 동일가중(미관측 종목은 현금 0%)
        cur = (1.0 + s).cumprod()
        yrs = max(len(s) / 252.0, 1e-9)
        cagr = float(cur.iloc[-1]) ** (1.0 / yrs) - 1.0
        mdd = float((cur / cur.cummax() - 1.0).min())
        _port.append({"티커": "★ 포트(동일가중)", "이름": f"{_n}종목", "산업ETF": "",
                      "전략": lbl, "총수익배수": round(float(cur.iloc[-1]), 4),
                      "CAGR": round(cagr, 4), "최대낙폭(MDD)": round(mdd, 4),
                      "칼마(CAGR/MDD)": (round(cagr / abs(mdd), 3) if mdd < -1e-9 else None),
                      "연변동성": round(float(s.std() * math.sqrt(252.0)), 4),
                      "샤프": (round(float(s.mean() / s.std() * math.sqrt(252.0)), 3)
                             if float(s.std()) > 0 else None),
                      "일간승률": round(float((s > 0).mean()), 4),
                      "평균노출": round(float(_W.mean(axis=1).mean()), 4)})
    # ---- [v0.7.0 R80 ★★] **실제 거래 행** — 06 시트 맨 위에 배분층 포트를 그대로 싣는다 ----
    #   위의 '★ 포트(동일가중)' 행들은 종목별 단독 신호를 동일가중한 **진단용**이다. 실제로 거래되는 것은
    #   배분층(build_allocation)이 만든 포트다. 사용자 지시("어떤 전략이 실제 거래에 쓰이는지 노란색")에 따라
    #   이 행을 만들고 리포트에서 이 행만 노란색으로 칠한다. 두 행이 다른 것은 정상이다(분배 방식이 다르다).
    _live_trade_lbl = f"★★ 실제 거래(배분층 {VERSION} · {alloc.get('mode', '-')})"
    try:
        _apr = alloc.get("port_ret")
        if _apr is not None and len(_apr):
            _ac = (1.0 + _apr.fillna(0.0)).cumprod()
            _ay = max(len(_apr) / 252.0, 1e-9)
            _acg = float(_ac.iloc[-1]) ** (1.0 / _ay) - 1.0
            _amd = float((_ac / _ac.cummax() - 1.0).min())
            _asd = float(_apr.std())
            _port.insert(0, {"티커": "★★ 실제 거래 포트", "이름": f"{len(panel)}종목",
                             "산업ETF": "", "전략": _live_trade_lbl,
                             "총수익배수": round(float(_ac.iloc[-1]), 4), "CAGR": round(_acg, 4),
                             "최대낙폭(MDD)": round(_amd, 4),
                             "칼마(CAGR/MDD)": (round(_acg / abs(_amd), 3) if _amd < -1e-9 else None),
                             "연변동성": round(_asd * math.sqrt(252.0), 4),
                             "샤프": (round(float(_apr.mean()) / _asd * math.sqrt(252.0), 3) if _asd > 0 else None),
                             "일간승률": round(float((_apr > 0).mean()), 4),
                             "평균노출": round(float(alloc["total_w"].mean()), 4)})
            log("PERF", kv(event="live_trade_row", label=_live_trade_lbl, cagr=round(_acg, 4),
                            mdd=round(_amd, 4), calmar=(round(_acg / abs(_amd), 3) if _amd < -1e-9 else None),
                            mean_exposure=round(float(alloc["total_w"].mean()), 4),
                            note="★ 06 시트에서 노란색으로 칠하는 행 — 실제 거래되는 포트"))
    except Exception as e:
        log("PERF", kv(event="live_trade_row_failed", err=type(e).__name__, msg=str(e)[:120]), level="warning")
    perf = _port + perf
    _pdf = pd.DataFrame(perf) if perf else pd.DataFrame(columns=["티커", "전략", "칼마(CAGR/MDD)"])
    _live = _live_lbl
    def _pick_calmar(lbl: str, tick: str = "★ 포트(동일가중)"):
        _m = _pdf[(_pdf["전략"] == lbl) & (_pdf["티커"] == tick)]["칼마(CAGR/MDD)"]
        return (round(float(_m.iloc[0]), 3) if len(_m) and pd.notna(_m.iloc[0]) else None)
    def _med(lbl: str):
        _m = _pdf[(_pdf["전략"] == lbl) & (_pdf["티커"] != "★ 포트(동일가중)")]["칼마(CAGR/MDD)"]
        return (round(float(_m.median(skipna=True)), 3) if len(_m) else None)
    log("PERF", kv(event="performance", rows=len(perf), port_rows=len(_port),
                    live_rule=cfg.LIVE_RULE,
                    port_calmar_live=_pick_calmar(_live), port_calmar_bh=_pick_calmar("매수보유"),
                    median_calmar_live=_med(_live), median_calmar_bh=_med("매수보유"),
                    note="포트 행은 동일가중 · 중위 행은 종목별 — 두 값은 일치하지 않는 것이 정상이다"))
    # [v0.4.0 R77] 00D 변형(체결 비중) — build_report가 I.build_updown_improvement_compare로 판정한다
    _ud = None
    if bool(getattr(cfg, "UPDOWN_COMPARE", True)):
        try:
            _ud = _updown_variants(panel, pos, cfg, mkt)
        except Exception as e:
            log("PERF", kv(event="updown_variants_failed", err=type(e).__name__, msg=str(e)[:160]), level="warning")
    return {"cfg": cfg, "panel": panel, "pos": pos, "prices": {**prices, **prices_h}, "fund": fund,
            "panel_h": panel_h, "pos_h": pos_h, "roles": roles, "automap": amap,           # [v0.6.0 R79]
            "universe": U, "names": _nm, "failed_px": dict(_FAILED_PX),
            "market_budget": mkt_info, "market_w": mkt, "updown": _ud, "live_label": _live_lbl,
            "live_trade_label": _live_trade_lbl,                                        # [v0.7.0 R80]
            "parent_of": parent_of, "accuracy": acc, "audit": audit,
            "alloc": alloc, "alloc_grid": pd.DataFrame(alloc_rows),
            "ind_alloc_info": ind_info, "alloc_controls": pd.DataFrame(_ctrl_rows),   # [v0.7.0 R80]
            "alloc_live_label": _live_alloc_label,                                     # [v0.8.0 R81]
            "quality": pd.DataFrame(quality), "perf": pd.DataFrame(perf),
            "fund_ledger": (pd.concat(fund_ledgers, ignore_index=True) if fund_ledgers
                            else pd.DataFrame()),
            "earn_ledger": (pd.concat(earn_ledgers, ignore_index=True) if earn_ledgers
                            else pd.DataFrame())}


def _versioned_path(path: str, enabled: bool = True) -> str:
    """[v0.8.1 R93] 'x.xlsx' → 'x_v0.8.1.xlsx'(M·S·I와 같은 규칙 · 예전 버전 꼬리는 떼고 붙인다)."""
    if not enabled or not path:
        return path
    import re as _re
    root, ext = os.path.splitext(str(path))
    root = _re.sub(r"_v\d+\.\d+\.\d+$", "", root)
    return f"{root}_{VERSION}{ext or '.xlsx'}"


def build_report(res: Dict[str, Any], path: Optional[str] = None, I=None) -> str:
    """[리포트] M·S·I와 같은 시트 어휘를 쓴다. I 모듈이 주어지면 19_상승하락구간을 그 함수로 만든다."""
    cfg: StockConfig = res.get("cfg", CFG)
    # [v0.8.1 R93] 설정에서 온 경로에만 버전을 붙인다(돌려주는 경로가 실제 파일 — 러너가 그대로 쓴다).
    path = path or _versioned_path(cfg.OUT_XLSX, bool(getattr(cfg, "OUT_XLSX_APPEND_VERSION", True)))
    sheets: Dict[str, pd.DataFrame] = {}
    if res.get("aborted"):
        sheets["00_실행요약"] = pd.DataFrame([{"항목": "판정", "값": res.get("note", "실행 실패")}])
        _write(path, sheets)
        return path
    panel: Dict[str, pd.DataFrame] = res["panel"]
    pos: Dict[str, pd.DataFrame] = res["pos"]
    parent_of = res["parent_of"]
    _NM: Dict[str, str] = dict(res.get("names") or {})            # [v0.6.0 R79] 임의 티커 이름(Yahoo shortName · 없으면 티커)
    _roles: Dict[str, str] = dict(res.get("roles") or {})

    # ---- 01Z 일별 예측 매트릭스(전 종목 한 시트) ----
    idx = sorted(set().union(*[set(v.index) for v in panel.values()]))
    idx = pd.DatetimeIndex(idx)
    # ---- 01Z [v0.3.0 D2·D3 전면 개편] ----
    #   D2: **배분비중**(총합 ≤ 1.0)이 주 열이 된다. 단독 신호(0/1)는 '단독신호' 열로 남겨 정보를 잃지 않는다.
    #       v0.2.1까지 '목표비중'이 티커마다 1.0이라 합계가 26.46이었다 — 사용자가 그것을 지적했다.
    #   D3: 맨 끝에 **다음 거래일 예측 행**을 붙인다(구분='예측'). S·I는 이미 있었고 K만 없었다.
    _aw = (res.get("alloc") or {}).get("target_w")
    # [v0.3.1 E4] 00_실행요약에도 비중 합계를 싣는다 — 00A를 열지 않아도 바로 보이게.
    _wsum_note = "배분층 없음"
    if isinstance(_aw, pd.DataFrame) and len(_aw):
        _ws = _aw.sum(axis=1)
        _ov = int((_ws > 1.0 + 1e-6).sum())
        _wsum_note = (f"일별 비중 합계 평균 {float(_ws.mean()):.4f} · 최대 {float(_ws.max()):.6f} · "
                      f"**1.0 초과일 {_ov}일** · 종목 최대비중 {float(_aw.max().max()):.4f} "
                      + ("→ ★ 전체자산 1.0 제약 준수" if _ov == 0 else "→ ⚠⚠ 제약 위반, 배분층 확인"))
    Z = pd.DataFrame(index=idx)
    for t in sorted(panel):
        Z[f"{t} 확정국면"] = pos[t]["확정국면"].reindex(idx)
        Z[f"{t} 단독신호"] = pos[t]["목표비중"].reindex(idx)
        Z[f"{t} 배분비중"] = (pd.to_numeric(_aw[t], errors="coerce").reindex(idx)
                           if isinstance(_aw, pd.DataFrame) and t in _aw.columns
                           else pd.Series(np.nan, index=idx))
    _wcols = [c for c in Z.columns if str(c).endswith("배분비중")]
    _tot = Z[_wcols].apply(pd.to_numeric, errors="coerce").sum(axis=1) if _wcols else pd.Series(0.0, index=idx)
    Z.insert(0, "현금", (1.0 - _tot).round(6))
    Z.insert(0, "★ 배분비중 합계", _tot.round(6))          # ★ 사용자 지적의 직접 확인 열
    Z.insert(0, "보유 종목수", sum((pos[t]["목표비중"].reindex(idx).fillna(0) > 0).astype(int)
                                for t in sorted(panel)))
    Z.insert(0, "구분", "실적")
    # ---- D3 다음 거래일 예측 행 ----
    #   t일 확정 → t+1일 집행이므로 **마지막 확정 행의 목표비중이 곧 다음 거래일의 집행 비중**이다.
    #   그것을 날짜만 다음 영업일로 바꿔 한 행 더 쓴다(새 계산이 아니라 체결 규칙의 명시다).
    try:
        if len(idx):
            # ★ 미국 공휴일을 건너뛴다 — 단순 bdate_range는 2026-01-01(신년)을 영업일로 본다
            #   (테스트가 잡았다). 달력을 못 만들면 영업일로 되돌린다.
            _nd = None
            try:
                from pandas.tseries.holiday import USFederalHolidayCalendar
                from pandas.tseries.offsets import CustomBusinessDay
                _cbd = CustomBusinessDay(calendar=USFederalHolidayCalendar())
                _nd = (idx[-1] + _cbd).normalize()
            except Exception:
                _nd = None
            if _nd is None:
                _nd = pd.bdate_range(idx[-1] + pd.Timedelta(days=1), periods=1)[0]
            _last = Z.iloc[[-1]].copy()
            _last.index = pd.DatetimeIndex([_nd])
            _last["구분"] = "예측(다음 거래일 집행)"
            Z = pd.concat([Z, _last])
            log("REPORT", kv(event="next_day_row_added", base=str(idx[-1].date()),
                             target=str(_nd.date()), w_sum=round(float(_tot.iloc[-1]), 4),
                             note="t일 확정 → t+1일 집행 규칙의 명시(새 계산 아님)"))
    except Exception as e:
        log("REPORT", kv(event="next_day_row_failed", err=str(e)[:150]), level="warning")
    sheets["01Z_주식일별예측"] = Z.reset_index().rename(columns={"index": "날짜"})
    # ---- [v0.3.0 D2] 13_주식배분전략 · 13c_일별배분비중 ----
    _ag = res.get("alloc_grid")
    if isinstance(_ag, pd.DataFrame) and len(_ag):
        sheets["13_주식배분전략"] = _ag
    if isinstance(_aw, pd.DataFrame) and len(_aw):
        _c13 = _aw.copy()
        _c13.insert(0, "★ 합계", _aw.sum(axis=1).round(6))
        _c13.insert(1, "현금", (1.0 - _aw.sum(axis=1)).round(6))
        sheets["13c_일별배분비중"] = _c13.reset_index().rename(columns={"index": "날짜"})

    # ---- 00 실행요약 ----
    meta: List[Tuple[str, Any]] = [
        ("제목", "미국 개별 주식 국면 예측 — M(시장)→S(섹터)→I(산업)→**K(개별 주식)** 4계층의 마지막 층"),
        ("★★ 전체자산 1.0 확인", _wsum_note),
        ("★ 00A_수익비교 시트", "맨 앞에 있음 — B&H 단순합 vs 단독예측 vs 전략(배분) 비교 + 비중 합계 감사"),
        ("버전", f"stock_regime.py {VERSION} ({VERSION_DATE})"),
        ("⚠ 실매매 적용 여부",
         "아니오 — 진단·연구용이다. 실매매 주문 근거는 market_regime_report.xlsx의 ★ SPY 국면전략이며, "
         "이 주식 계층은 v0.1.0(첫 버전)으로 **예측 채점**이 본체다."),
        ("표본", (f"설계 {sum(1 for t in panel if _roles.get(t) == '설계')}종목(산업 ETF마다 대표 1개) · "
                 f"사용자 입력 {sum(1 for t in panel if _roles.get(t) == '사용자')}종목 = 라이브·배분 {len(panel)}종목"
                 f" · 홀드아웃(검증 전용) {len(res.get('panel_h') or {})}종목 — 입력: k_overrides={{'TICKERS': (…)}} 또는 "
                 "{'EXTRA_TICKERS': (…)} · 산업 ETF 자동 매핑(02 '매핑 방법')")),
        ("평가창", f"{cfg.EVAL_START} ~ {str(idx[-1].date()) if len(idx) else '-'} "
                 f"({len(idx)}거래일) · 특성 워밍업 {cfg.START}부터"),
        ("★ 라이브 규칙(v0.4.0 R77 · ⚠⚠ 위험 파라미터)",
         (f"{cfg.LIVE_RULE} × M 시장 예산 — 목표비중 = min(기본 1.0 · E3(음의 어닝 서프라이즈 후 21일) 0, **M E_t**). "
          "v0.3.3까지는 M을 보지 않아(평균 노출 ≈0.95) 시장 하락을 구조적으로 피할 수 없었다. I 계층과 같은 시장 예산을 쓴다. "
          "되돌리기: k_overrides={'MARKET_BUDGET': 'none'}")
         if (res.get("market_budget") or {}).get("ok") else
         (f"{cfg.LIVE_RULE} — 기본 1.0, E3(음의 어닝 서프라이즈 후 21일)만 0. ⚠ 시장 예산(M E_t) **미적용** — "
          f"사유: {(res.get('market_budget') or {}).get('note', '-')}")),
        ("⚠ 시장 예산(M E_t) 출처",
         (lambda _m: (f"{_m.get('source', '-')} · 마지막일 {_m.get('asof', '-')} · {_m.get('rows', 0)}행 · "
                      f"평균 E_t {_m.get('mean', '-')} · {_m.get('note', '')}"))(res.get("market_budget") or {})),
        ("★ 펀더멘탈 인과 처리",
         f"분기 재무는 **기간말이 아니라 유효일** 기준 as-of로만 쓴다 — 실제 발표일 우선, 없으면 "
         f"기간말 + {cfg.FUND_PUBLISH_LAG_DAYS}일(10-K 기한 60일 기준의 보수 상한). "
         "'다음 어닝까지 며칠' 류는 과거 시점에 알 수 없으므로 **특성에 넣지 않았다**. "
         "04_펀더멘탈원장의 '유효일 출처' 열에서 티커별로 확인할 수 있고, 11_룩어헤드감사가 "
         "절단재계산으로 매 실행 검증한다."),
        ("판정 잣대", "소수 클래스 기준(정밀도는 항상 기저율과 함께) · 연도 k/n이 1급 · 자기이력 백분위로만 단면 비교"),
        ("면책", "본 산출물은 연구·교육 목적의 백테스트이며 투자 자문이 아니다."),
    ]
    aud = res.get("audit", pd.DataFrame())
    if len(aud):
        bad = int((aud["일치"].astype(str).str.startswith("⚠")).sum())
        meta.append(("룩어헤드 감사", f"검사 {len(aud)}건 · 불일치 **{bad}건**"
                                 + (" — 통과" if bad == 0 else " ⚠ 조사 필요")))
    pf = res.get("perf", pd.DataFrame())
    if len(pf):
        # [v0.4.0 R77 버그수정] 라이브 행 라벨은 v0.2.0부터 '★ 라이브(…)'였다 — '전략'으로 찾아 늘 빈 표(NaN)였다.
        _ll = str(res.get("live_label") or f"★ 라이브({cfg.LIVE_RULE})")
        st = pf[pf["전략"].astype(str).eq(_ll) & (pf["티커"].astype(str) != "★ 포트(동일가중)")]
        bh = pf[pf["전략"].astype(str).eq("매수보유") & (pf["티커"].astype(str) != "★ 포트(동일가중)")]
        meta.append(("라이브 규칙 성과(중위)",
                     f"전략 CAGR {st['CAGR'].median():.4f} · MDD {st['최대낙폭(MDD)'].median():.4f} · "
                     f"칼마 {st['칼마(CAGR/MDD)'].median(skipna=True):.3f} vs "
                     f"매수보유 CAGR {bh['CAGR'].median():.4f} · MDD {bh['최대낙폭(MDD)'].median():.4f} · "
                     f"칼마 {bh['칼마(CAGR/MDD)'].median(skipna=True):.3f} "
                     f"({len(panel)}종목 중위값 — 개별 종목 표는 06 시트)"))
    # 다음 거래일 예측
    if len(idx):
        last = idx[-1]
        nd = []
        for t in sorted(panel):
            p = pos[t]
            if last in p.index:
                nd.append(f"{t}({_NM.get(t, STOCK_NAME_KR.get(t, t))}) {p['확정국면'].loc[last]}/"
                          f"{float(p['목표비중'].loc[last]):.2f}")    # [v0.4.0] E_t 부분 노출(0.4~0.6)을 반올림하지 않는다
        meta.append((f"다음 거래일 예측({last.date()} 확정 → 익일 집행)", " · ".join(nd)))
    sheets["00_실행요약"] = pd.DataFrame(meta, columns=["항목", "값"])
    sheets["02_티커요약"] = res["quality"]
    sheets["03_예측규칙정확도"] = res["accuracy"]
    _drop = set(tuple(getattr(cfg, "REPORT_DROP_SHEETS", ()) or ()))       # [v0.4.0 R77]
    if len(res.get("fund_ledger", pd.DataFrame())) and "04_펀더멘탈원장" not in _drop:
        sheets["04_펀더멘탈원장"] = res["fund_ledger"]
    if len(res.get("earn_ledger", pd.DataFrame())):
        sheets["05_어닝이벤트"] = res["earn_ledger"]
    sheets["06_성과요약"] = pf
    if len(aud):
        sheets["11_룩어헤드감사"] = aud

    # ---- 19_상승하락구간 (I 모듈 함수 재사용) ----
    if bool(getattr(cfg, "SHOW_UPDOWN_SEGMENTS", True)) and I is not None:
        try:
            ret = pd.DataFrame({t: pd.to_numeric(panel[t]["일간수익"], errors="coerce")
                                for t in sorted(panel)}).reindex(idx)
            cur = (1.0 + ret.fillna(0.0)).cumprod()
            ex = pd.DataFrame({t: pd.to_numeric(pos[t]["집행비중"], errors="coerce")
                               for t in sorted(panel)}).reindex(idx).fillna(0.0)
            seg = I.build_up_down_segments(
                cur, ex, ret, cfg,
                name_map={t: _NM.get(t, STOCK_NAME_KR.get(t, t)) for t in sorted(panel)},
                parent_map={t: parent_of.get(t, "") for t in sorted(panel)},
                bench_w=None,          # 주식 계층의 비중 예산은 1.0이므로 완전 참여가 도달 가능한 벤치다
                layer="개별주식", M=None)
            # [v0.4.0 R77] 블록 A′(단독 라이브 판정 — I와 같은 함수·같은 문턱) 맨 앞. 00시트 '★ 단일 종목 라이브 예측 vs B&H'의 출처.
            if hasattr(I, "build_single_live_segments"):
                try:
                    _ap = I.build_single_live_segments(
                        cur, ex, ret, cfg, own_exec=None,
                        name_map={t: _NM.get(t, STOCK_NAME_KR.get(t, t)) for t in sorted(panel)},
                        parent_map={t: parent_of.get(t, "") for t in sorted(panel)}, M=None)
                    if isinstance(_ap, pd.DataFrame) and len(_ap):
                        seg = pd.concat([_ap, seg], ignore_index=True) if isinstance(seg, pd.DataFrame) else _ap
                except Exception as e:
                    log("REPORT", kv(event="single_live_segments_failed", err=type(e).__name__, msg=str(e)[:160]),
                        level="warning")
            # ---- (K5 ★ 신규) 블록 C — 포트폴리오 구간(동일가중 B&H 대비) ----
            # 왜 필요한가: 블록 A는 "그 **종목**의 상승을 탔나"를 묻는다. 주식 계층은 종목마다
            # 예산이 1.0이라 블록 A도 도달 가능한 벤치를 쓰지만, "이 **계층 전체**가 B&H 대비
            # 하락을 피했고 상승을 탔나"는 별개의 질문이며 그것이 사용자가 묻는 단위다.
            #   · 전략 포트 = 29종목 **동일가중**, 각 종목은 자기 집행비중만큼 참여
            #   · 벤치      = 29종목 **동일가중 B&H**(항상 1.0) — 같은 종목·같은 가중이므로 도달 가능
            #   · 총노출    = 집행비중의 종목 평균(0~1). 1.0이면 전량 보유, 0이면 전량 현금.
            # [v0.3.0 D2] ★ 블록 C는 **배분층의 실제 비중**을 쓴다(총합 ≤ 1.0).
            #   v0.2.1까지는 ex(티커별 0/1)를 종목수로 나눠 '동일가중인 척' 만들었는데, 그것은
            #   엔진이 실제로 집행한 비중이 아니었다. 이제 배분층이 있으므로 그럴 필요가 없다.
            _alw = (res.get("alloc") or {}).get("exec_w")
            _n = max(1, ret.shape[1])
            _bh_r = ret.fillna(0.0).mean(axis=1)                    # 동일가중 B&H(총 1.0)
            if isinstance(_alw, pd.DataFrame) and len(_alw):
                _aex = _alw.reindex(index=idx, columns=ret.columns).astype(float).fillna(0.0)
                _st_r = (ret.fillna(0.0) * _aex).sum(axis=1)        # 배분 포트 일간수익
                _expo = _aex.sum(axis=1)                            # ★ 총노출 = 비중 합계(0~1)
                _plabel = f"★ 전략(배분 · {(res.get('alloc') or {}).get('mode', '?')})"
            else:
                _st_r = (ret.fillna(0.0) * ex).sum(axis=1) / float(_n)
                _expo = ex.mean(axis=1)
                _plabel = "★ 전략(동일가중 · 배분층 없음)"
            segc = I.build_portfolio_segments(
                (1.0 + _st_r).cumprod(), _expo, (1.0 + _bh_r).cumprod(), cfg,
                bench_label=f"{ret.shape[1]}종목 동일가중 B&H", layer="개별주식",
                port_label=_plabel, M=None)
            if isinstance(segc, pd.DataFrame) and len(segc):
                seg = pd.concat([seg, segc], ignore_index=True) if isinstance(seg, pd.DataFrame) else segc
            if isinstance(seg, pd.DataFrame) and len(seg):
                sheets["19_상승하락구간"] = seg
        except Exception as e:
            log("REPORT", kv(event="updown_segments_failed", err=str(e)[:200]), level="warning")
    # ---- [v0.3.0 D1 ★ 신규 시트] 00A_수익비교 (맨 앞) ----
    #   사용자 지시: "각 주식별 buy and hold시 수익률(복리가 아닌 변동률 합산)과 단독 예측으로
    #   거래 시 수익률 비교하고 전략 수익률도 같이 표시해"
    if I is not None and hasattr(I, "build_asset_return_compare"):
        try:
            _a = res.get("alloc") or {}
            _ret0 = pd.DataFrame({t: pd.to_numeric(panel[t]["일간수익"], errors="coerce")
                                  for t in sorted(panel)}).reindex(idx)
            _aex0 = (_a.get("exec_w") if isinstance(_a.get("exec_w"), pd.DataFrame) else None)
            _aex0 = (_aex0.reindex(index=idx, columns=_ret0.columns).fillna(0.0)
                     if _aex0 is not None else
                     pd.DataFrame(0.0, index=idx, columns=_ret0.columns))
            # 단독예측 비중 = build_positions의 집행비중(티커마다 0/1 — 그 종목만 100% 운용했을 때)
            _sw0 = pd.DataFrame({t: pd.to_numeric(pos[t]["집행비중"], errors="coerce")
                                 for t in sorted(panel)}).reindex(idx).fillna(0.0)
            _cmp0 = I.build_asset_return_compare(
                _ret0, _aex0, cfg, solo_w=_sw0,
                name_map={t: _NM.get(t, STOCK_NAME_KR.get(t, t)) for t in sorted(panel)},
                parent_map={t: parent_of.get(t, "") for t in sorted(panel)},
                layer="개별주식", M=None)
            if isinstance(_cmp0, pd.DataFrame) and len(_cmp0):
                sheets["00A_수익비교"] = _cmp0
        except Exception as e:
            # ★★ [v0.3.1 E3] 실패해도 시트는 반드시 쓴다 — 조용히 빠지면 사용자는 "왜 안 만들었어"만 본다.
            import traceback as _tb
            log("REPORT", kv(event="asset_return_compare_failed", err=str(e)[:200]), level="error")
            sheets["00A_수익비교"] = pd.DataFrame([{
                "블록": "A. 자산별 수익 비교", "자산": "⚠ 산출 실패",
                "판정": (f"00A 생성 중 예외: {type(e).__name__}: {str(e)[:220]} / "
                       "다음 단계: (1) run_pipeline이 I 모듈을 넘겼는지(I=None이면 00A가 안 나온다) "
                       "(2) res['alloc']['exec_w']가 있는지 (3) 로그 전체 메시지 확인."),
                "추적": _tb.format_exc()[-800:]}])
    elif I is None:
        # I를 못 받으면 00A 함수 자체가 없다 — 그것도 시트로 알린다(무음 금지).
        sheets["00A_수익비교"] = pd.DataFrame([{
            "블록": "A. 자산별 수익 비교", "자산": "⚠ 생략됨",
            "판정": ("I(industry_rotation) 모듈을 받지 못해 00A를 만들 수 없었다. "
                   "K는 I의 build_asset_return_compare를 재사용한다. "
                   "다음 단계: run_pipeline.main()으로 실행하거나 "
                   "stock_regime.main(I=industry_rotation)처럼 I를 넘길 것.")}])
    # ---- [v0.4.0 R77 ★] 00D_하락상승개선비교 — I.build_updown_improvement_compare(단일 출처) ----
    _udv = res.get("updown")
    if bool(getattr(cfg, "UPDOWN_COMPARE", True)):
        if I is not None and hasattr(I, "build_updown_improvement_compare") and isinstance(_udv, dict):
            try:
                _ret1 = pd.DataFrame({t: pd.to_numeric(panel[t]["일간수익"], errors="coerce")
                                      for t in sorted(panel)}).reindex(idx)
                _cur1 = (1.0 + _ret1.fillna(0.0)).cumprod().where(_ret1.notna() | _ret1.ffill().notna())
                _V = {k: v.reindex(idx) for k, v in (_udv.get("variants") or {}).items()}
                # [v0.5.0 R78] ML 워크포워드 후보 — 종목 가격 전 이력(START부터)·M E_t·시장 대용(종목 동일가중)
                _mlk: Dict[str, Any] = {"ok": False, "note": "끔(ML_COMPARE=False) 또는 I에 ML 함수 없음"}
                _ml_lbls: List[str] = []
                _cands = list(_udv.get("cands") or ())
                if bool(getattr(cfg, "ML_COMPARE", True)) and hasattr(I, "ml_timing_walkforward"):
                    try:
                        _curv = {t: pd.to_numeric(res["prices"][t]["Close"], errors="coerce") for t in sorted(panel)
                                 if t in (res.get("prices") or {})}
                        _mlk = I.ml_timing_walkforward(_curv, res.get("market_w"), None, cfg,
                                                       first_test_year=int(pd.Timestamp(cfg.EVAL_START).year),
                                                       layer="종목", M=None)
                        if _mlk.get("ok"):
                            _tgt = {t: pd.to_numeric(pos[t]["목표비중"], errors="coerce") for t in sorted(panel)}
                            _mv = I.ml_variants_from(_tgt, _tgt, _mlk)
                            _exs = lambda d: pd.DataFrame(d).reindex(idx).ffill().shift(1).fillna(0.0)
                            _l1 = "후보: + 부분 노출일 ML 컷(p<학습중위)"
                            _l2 = "참고: ML(GBM) 단독 — p≥학습중위면 1"
                            _V[_l1] = _exs(_mv["mid_cut"]); _V[_l2] = _exs(_mv["solo"])
                            (_udv.get("desc") or {}).update({_l1: "0<E_t<1 날 ML 확률이 학습 중위 미만이면 0 — 표본 밖 연도만",
                                                             _l2: "M 예산 없이 ML 확률만으로 0/1 — 표본 밖 연도만"})
                            _cands.append(_l1); _ml_lbls = [_l1, _l2]
                    except Exception as e:
                        _mlk = {"ok": False, "note": f"실패 {type(e).__name__}: {str(e)[:140]}"}
                        log("REPORT", kv(event="ml_compare_failed", err=type(e).__name__, msg=str(e)[:160]), level="warning")
                _ud = I.build_updown_improvement_compare(
                    _cur1, _ret1, _V, cfg, ref_label=_udv["ref"], old_label=_udv.get("old"),
                    market_exec=_udv.get("market_exec"), candidate_labels=tuple(_cands),
                    falsify_labels=tuple(_udv.get("fals") or ()), descriptions=_udv.get("desc"),
                    name_map={t: _NM.get(t, STOCK_NAME_KR.get(t, t)) for t in sorted(panel)},
                    parent_map={t: parent_of.get(t, "") for t in sorted(panel)},
                    layer="종목", cost_bps=10.0, M=None)
                if hasattr(I, "_append_ml_block"):
                    _ud = I._append_ml_block(_ud, _mlk, _V, _ret1, _udv["ref"],
                                             [l for l in (_udv["ref"], _udv.get("old")) if l and l in _V] + _ml_lbls, 10.0, "종목")
                if isinstance(_ud, pd.DataFrame) and len(_ud):
                    sheets["00D_하락상승개선비교"] = _ud
            except Exception as e:
                log("REPORT", kv(event="updown_compare_failed", err=type(e).__name__, msg=str(e)[:200]), level="warning")
                sheets["00D_하락상승개선비교"] = pd.DataFrame([{"블록": "A", "변형": "⚠ 산출 실패",
                                                           "판정": f"{type(e).__name__}: {str(e)[:220]}"}])
        else:
            sheets["00D_하락상승개선비교"] = pd.DataFrame([{"블록": "A", "변형": "⚠ 생략됨",
                                                       "판정": ("I(industry_rotation v0.31.0+) 모듈이 없거나 변형이 비었다 — "
                                                              "run_pipeline.main()으로 실행하거나 build_report(res, I=industry_rotation)")}])
    # ---- [v0.6.0 R79 ★★] 00G_일반화검증 — 설계 종목 vs 처음 보는(홀드아웃) 종목, 같은 규칙 ----
    _gen_line = "-"
    try:
        _gdf, _gen_line = build_generalization_sheet(res, I=I)
        if isinstance(_gdf, pd.DataFrame) and len(_gdf):
            sheets["00G_일반화검증"] = _gdf
    except Exception as e:
        _gen_line = f"산출 실패 {type(e).__name__}: {str(e)[:140]}"
        log("REPORT", kv(event="generalization_failed", err=type(e).__name__, msg=str(e)[:160]), level="warning")
    # ---- [v0.4.0 R77] 00시트 판정 3행 — 수치는 시트에서 읽는다 ----
    try:
        _m0 = list(sheets["00_실행요약"].itertuples(index=False, name=None))
        _add: List[Tuple[str, Any]] = []
        if I is not None and hasattr(I, "single_live_verdict_line"):
            _add.append(("★ 단일 종목 라이브 예측 vs B&H(하락 회피·상승 참여)",
                         str(I.single_live_verdict_line(sheets)).replace("(산업 합)", "(종목 합)")))
        if isinstance(sheets.get("00D_하락상승개선비교"), pd.DataFrame) and I is not None and hasattr(I, "updown_compare_line"):
            _add.append(("★ 00D_하락상승개선비교 — 개선 방향", I.updown_compare_line(sheets["00D_하락상승개선비교"])))
        _dd = [n for n in sorted(_drop) if n == "04_펀더멘탈원장" and len(res.get("fund_ledger", pd.DataFrame()))]
        if _dd:
            _add.append(("제거한 시트(v0.4.0 R77)", ", ".join(_dd) + " — F 계열(라이브 미사용) 원장 · 티커별 유효일 출처는 02에 있다. "
                         "되돌리기: k_overrides={'REPORT_DROP_SHEETS': ()}"))
        _add.append(("★ 00G_일반화검증 — 처음 보는 종목에서도 되나(사전등록 홀드아웃)", _gen_line))
        # ---- [v0.7.0 R80 · v0.8.0 R81] 배분 방식 · 출처 · 대조군 판정 ----
        _ii = dict(res.get("ind_alloc_info") or {})
        _al = res.get("alloc") or {}
        _td = dict(_al.get("tilt") or {})
        _md = str(_al.get("mode", "-"))
        if _md == "prob_tilt" and _td.get("ok"):
            _mline = (f"mode=prob_tilt(상승확률 기울임) · λ={_td.get('lam')} · 점수제곱={_td.get('power')} · 종목상한 "
                      f"{float(_td.get('cap', cfg.STOCK_MAX_WEIGHT)):.0%} · 점수=산업 **결합점수 백분위**(섹터·산업·변동성 지표) · "
                      f"점수 받은 종목 {_td.get('covered')}/{_td.get('n')} · 보유종목 비중 변동계수 {_td.get('cv_mean')} · "
                      f"**상위5종목 몫 {float(_td.get('top5_share') or 0) * 100:.1f}%**(1/N이면 {500.0 / max(1, int(_td.get('n') or 1)):.1f}%) · "
                      f"총노출 오차 최대 {_td.get('tot_gap_max', 0)}")
        elif _md == "industry_tilt" and _td.get("ok"):
            _mline = (f"mode=industry_tilt · λ={_td.get('lam', '-')} · 연동 적용 종목비율 평균 {_td.get('cover_mean', '-')} · "
                      f"자료부족으로 1/N만 쓴 날 {_td.get('thin_days', '-')}일")
        else:
            _mline = f"mode={_md} — ⚠ {str(_td.get('note') or _ii.get('note') or '점수 출처 없음 — 1/N 고정슬리브')}"
        _add.append(("★ 배분 방식(v0.8.0 · 사용자 지시 '다 똑같이 주지 말고 상승확률 높은 것에')",
                     _mline + " ★ 총노출(=방어)은 v0.6.0 1/N 규칙과 날마다 동일하다 — 바뀐 것은 그 노출의 종목 간 분배뿐이다."))
        _add.append(("점수·비중 출처(K는 runner 수정 없이 I 통로에서 스스로 찾는다)",
                     f"{_ii.get('source', '-')} · 결합점수 산업 {_ii.get('coupling_cols', 0)}개 · 산업비중 {_ii.get('industries', 0)}개 · "
                     f"부모(섹터) 다리 {_ii.get('parents', 0)}개 · 기준일 {_ii.get('asof', '-')} · {_ii.get('note', '-')}"))
        try:
            _ag2 = res.get("alloc_grid")
            _cdf2 = res.get("alloc_controls")
            if isinstance(_ag2, pd.DataFrame) and len(_ag2) and isinstance(_cdf2, pd.DataFrame) and len(_cdf2):
                _lvl = str(res.get("alloc_live_label") or "")
                _lv = _ag2[_ag2["배분방식"].astype(str) == _lvl] if _lvl else _ag2.iloc[0:0]
                _bs = _ag2[_ag2["배분방식"].astype(str).str.startswith("고정슬리브 1/N")]
                _cq = pd.to_numeric(_cdf2["칼마(CAGR/MDD)"], errors="coerce").dropna()
                _cg2 = pd.to_numeric(_cdf2["CAGR"], errors="coerce").dropna()
                if len(_lv) and len(_cq):
                    _lc = float(pd.to_numeric(_lv["칼마(CAGR/MDD)"], errors="coerce").iloc[0])
                    _lg = float(pd.to_numeric(_lv["CAGR"], errors="coerce").iloc[0])
                    _bc = (float(pd.to_numeric(_bs["칼마(CAGR/MDD)"], errors="coerce").iloc[0]) if len(_bs) else float("nan"))
                    _bg = (float(pd.to_numeric(_bs["CAGR"], errors="coerce").iloc[0]) if len(_bs) else float("nan"))
                    _pr_c = float((_cq < _lc).mean()) * 100.0
                    _pr_g = float((_cg2 < _lg).mean()) * 100.0
                    _pass = (_pr_c >= 90.0) and (_lc >= _bc - 1e-9)
                    _add.append(("★ 점수에 정보가 있나 — 무작위 대조군 판정(13 시트 · 사전등록 R81)",
                                 f"라이브 CAGR {_lg * 100:.2f}% · 칼마 {_lc:.3f} | 1/N CAGR {_bg * 100:.2f}% · 칼마 {_bc:.3f} | "
                                 f"대조군({len(_cq)}회) 칼마 중앙 {_cq.median():.3f} · 상위5% {_cq.quantile(0.95):.3f} → "
                                 f"라이브 백분위 칼마 {_pr_c:.0f} · CAGR {_pr_g:.0f} "
                                 + ("→ ★ 통과(사전등록: 칼마 백분위 ≥ 90 그리고 칼마 ≥ 1/N)" if _pass else
                                    "→ ⚠ 미통과(사전등록: 칼마 백분위 ≥ 90 그리고 칼마 ≥ 1/N) — 다음 라운드에 되돌린다. "
                                    "되돌리기: k_overrides={'STOCK_ALLOC_MODE': 'equal_fixed'}")))
        except Exception as e:
            log("REPORT", kv(event="tilt_verdict_line_failed", err=type(e).__name__, msg=str(e)[:120]), level="warning")
        _add.append(("★ 노란색 표시(M·S·I·K 공통 약속 · R80~)",
                     "노란색 행 = **실제 거래에 쓰는 전략**이다. K는 13_주식배분전략의 라이브 배분 행과 "
                     "06_성과요약의 '★★ 실제 거래 포트' 행이 노란색이다. 06의 '★ 포트(동일가중)' 행들은 "
                     "종목별 단독 신호를 동일가중한 **진단용**이고 실제 거래가 아니다."))
        _am = res.get("automap") or {}
        _ur = res.get("universe") or {}
        _add.append(("유니버스 · 산업 ETF 매핑(v0.6.0)",
                     " · ".join(f"{k} {v}" for k, v in pd.Series([str((_am.get(t) or {}).get('method', '-')).split('(')[0]
                                                                   for t in _am]).value_counts().items())
                     + (" · 입력 제외: " + ", ".join(f"{a}({b})" for a, b in (_ur.get("dropped") or [])) if _ur.get("dropped") else "")
                     + (" · 다운로드 실패: " + ", ".join(f"{k}({v[:40]})" for k, v in (res.get("failed_px") or {}).items())
                        if res.get("failed_px") else "")))
        if _add:
            sheets["00_실행요약"] = pd.DataFrame(_m0[:2] + _add + _m0[2:], columns=["항목", "값"])
    except Exception as e:
        log("REPORT", kv(event="r77_meta_failed", err=type(e).__name__, msg=str(e)[:120]), level="warning")
    for t in sorted(panel):
        d = pd.concat([panel[t], pos[t]], axis=1)
        if isinstance((res.get("alloc") or {}).get("target_w"), pd.DataFrame):
            _tw0 = (res["alloc"]["target_w"])
            if t in _tw0.columns:
                d["배분목표비중"] = pd.to_numeric(_tw0[t], errors="coerce").reindex(d.index)
                d["배분집행비중"] = pd.to_numeric(res["alloc"]["exec_w"][t],
                                            errors="coerce").reindex(d.index)
        sheets[f"01_일별_{t}"] = d.reset_index().rename(columns={"index": "날짜"})
    # 맨 앞으로: 00A → 01Z → 00 → 나머지
    _front = [n for n in ("00A_수익비교", "00D_하락상승개선비교", "00G_일반화검증", "01Z_주식일별예측", "00_실행요약") if n in sheets]
    sheets = {**{n: sheets[n] for n in _front},
              **{k: v for k, v in sheets.items() if k not in _front and k not in _drop}}
    # [v0.7.0 R80] ★ 실제 거래에 쓰는 전략 행을 노란색으로 — 13(배분)·06(노출)·00A(수익비교) 세 곳
    _lm: Dict[str, Any] = {}
    try:
        _ag = res.get("alloc_grid")
        if isinstance(_ag, pd.DataFrame) and "배분방식" in _ag.columns:
            _liveb = str(res.get("alloc_live_label") or "") or None
            if _liveb is None:
                _liveb = next((str(v) for v in _ag["배분방식"].astype(str) if "라이브" in v), None)
            if _liveb:
                _lm["13_주식배분전략"] = ("배분방식", _liveb)
        _ll = str(res.get("live_trade_label") or "")
        if _ll:
            _lm["06_성과요약"] = ("전략", _ll)      # ★ 배분층 = 실제 거래되는 포트
    except Exception as e:
        log("REPORT", kv(event="live_marks_build_failed", err=type(e).__name__, msg=str(e)[:120]), level="warning")
    _write(path, sheets, live_marks=(_lm or None))
    _mb = (os.path.getsize(path) / 1e6) if os.path.exists(path) else float("nan")
    log("REPORT", kv(event="written", path=path, sheets=len(sheets), size_mb=round(_mb, 2),
                     note="사용자 제약: 리포트 파일 전체 30MB 이하"))
    if _mb > 30.0:
        log("REPORT", kv(event="size_over_limit", size_mb=round(_mb, 2),
                         suggest="SEG_DETAIL_MAX를 줄이거나 01_일별_* 시트를 끄는 것을 검토"),
            level="warning")
    return path


def _write(path: str, sheets: Dict[str, pd.DataFrame],
           live_marks: Optional[Dict[str, Any]] = None) -> None:
    """[v0.7.0 R80] live_marks = {시트명: (열이름, 값) 또는 [(열이름, 값), …]} — 그 열 값이 일치하는 **행 전체를 노란색**으로 칠한다.
    사용자 지시(2026-09-21) "각 계층별로 어떤 전략이 실제 거래에 사용되는지 노란색으로 표시해" — M·S·I와 같은 약속이다.
    M 모듈이 같은 프로세스에 있으면 M.apply_live_marks를 그대로 쓰고(서식 단일 출처), 없으면 여기서 같은 규칙으로 칠한다."""
    _M = None
    for _nm, _mod in list(sys.modules.items()):
        if callable(getattr(_mod, "apply_live_marks", None)) and callable(getattr(_mod, "_live_row_format", None)):
            _M = _mod
            break
    with pd.ExcelWriter(path, engine="xlsxwriter") as xw:
        wb = xw.book
        f_live = (_M._live_row_format(wb) if _M is not None
                  else wb.add_format({"bg_color": "#FFF200", "bold": True, "border": 1}))
        for name, df in sheets.items():
            d = df if isinstance(df, pd.DataFrame) else pd.DataFrame(df)
            nm = str(name)[:31]
            d.to_excel(xw, sheet_name=nm, index=False)
            if not live_marks or nm not in live_marks or not len(d):
                continue
            try:
                if _M is not None:
                    _M.apply_live_marks(xw.sheets[nm], wb, d, nm, live_marks, f_live)
                    continue
                from xlsxwriter.utility import xl_col_to_name
                w_ = xw.sheets[nm]
                cols = list(d.columns)
                pairs = live_marks[nm]
                pairs = pairs if isinstance(pairs, list) else [pairs]
                for col, val in pairs:
                    if col not in cols:
                        continue
                    cl = xl_col_to_name(cols.index(col))
                    w_.conditional_format(1, 0, len(d), len(cols) - 1,
                                          {"type": "formula",
                                           "criteria": f'=${cl}2="{str(val)}"', "format": f_live})
            except Exception as e:
                log("REPORT", kv(event="live_mark_failed", sheet=nm, err=type(e).__name__,
                                 msg=str(e)[:120]), level="warning")


def main(s_overrides: Optional[Dict[str, Any]] = None, I=None,
         parent_w: Optional[pd.DataFrame] = None) -> str:
    """단독 실행 진입점. run_pipeline이 I 모듈을 넘겨 주면 19·00A 시트가 함께 나오고,
    parent_w(I의 산업 비중)를 넘겨 주면 배분격자의 4계층 정합 행이 살아난다."""
    res = run(CFG, s_overrides, parent_w=parent_w)
    return build_report(res, I=I)


if __name__ == "__main__":
    print(f"stock_regime.py {VERSION} ({VERSION_DATE}) — 개별 주식 계층(K). "
          f"산업별 대표 티커 {len(STOCK_UNIVERSE)}종 · 펀더멘탈·어닝 포함. "
          f"실행: main() 또는 run_pipeline.py")
